INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_rules_general', 'Battleground Basics', 'Battlegrounds are instanced PvP matches queued for from any Battlemaster NPC or the Battleground UI; most use standard 10-level brackets, though Alterac Valley opens at level 51 and Eye of the Storm, Strand of the Ancients, and Isle of Conquest all require at least level 61-71. Winning awards a burst of Honor plus a Mark of Honor for that battleground, spent at PvP quartermasters on battleground-specific gear, while losing still pays a smaller Honor reward. Patch 3.3.3 added the Random Battleground queue, replacing the old daily battleground quests with a bonus of Honor and Arena Points for the day''s first win; the featured ''Call to Arms'' battleground of the day pays that same bonus for queuing it directly instead of random.', 'battlegrounds,battlemaster,marks of honor,random battleground,call to arms,pvp brackets,quartermaster', 'pvp,battlegrounds,mechanic');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_warsong_gulch', 'Warsong Gulch', 'Warsong Gulch is a capture-the-flag battleground fought 10-a-side between Horde and Alliance camps in a fenced-off stretch of Ashenvale forest. The first team to carry the enemy''s flag back to their own flag room three times wins the match; a dropped flag resets after a short time if nobody picks it up. It is the lowest-level battleground, open to characters starting at level 10, and is often a new player''s first taste of organized PvP.', 'warsong gulch,wsg,capture the flag,flag room,ashenvale', 'pvp,battlegrounds,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_arathi_basin', 'Arathi Basin', 'Arathi Basin is a resource-control battleground played 15-a-side over five capturable nodes -- the Blacksmith, Farm, Gold Mine, Lumber Mill, and Stables -- scattered across a stretch of the Arathi Highlands. Holding a node generates resources for your team every few seconds, so controlling more nodes at once matters more than any single capture. The first team to reach 2000 resources wins, or whichever team is ahead if the match runs its full length. It opens to characters at level 20.', 'arathi basin,ab,resource nodes,blacksmith,gold mine,lumber mill,stables', 'pvp,battlegrounds,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_alterac_valley', 'Alterac Valley', 'Alterac Valley is the largest battleground, fought up to 40-a-side across the long mountain valley connecting the Horde''s Frostwolf Keep to the Alliance''s Dun Baldar. Each side wins by pushing all the way to the enemy base and killing its final boss -- Alliance players kill Drek''Thar, Horde players kill Vanndar Stormpike -- while capturing towers and graveyards along the way weakens the enemy''s reinforcements. Its original Vanilla form could run for hours and required razing every enemy tower, bunker, and field commander first; a later redesign cut that down to a much faster rush on the boss, so a 3.3.5a match usually finishes in well under 20 minutes. It opens to characters at level 51, the highest minimum of any standard battleground.', 'alterac valley,av,drek''thar,vanndar stormpike,frostwolf keep,dun baldar', 'pvp,battlegrounds,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_eye_of_the_storm', 'Eye of the Storm', 'Eye of the Storm is a 15-a-side battleground on a floating island in Netherstorm that blends flag-carrying with resource-node control. Teams fight over four capturable towers -- the Blood Elf Tower, Draenei Ruins, Mage Tower, and Fel Reaver Ruins -- that each generate points over time, and picking up the flag at the center of the map and holding it while your team controls nodes adds a large points bonus. The first team to 1600 points wins, or whichever team is ahead when the match''s timer expires. It was added in the Burning Crusade and opens to characters at level 61.', 'eye of the storm,eots,netherstorm,blood elf tower,draenei ruins,mage tower,fel reaver', 'pvp,battlegrounds,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_strand_of_the_ancients', 'Strand of the Ancients', 'Strand of the Ancients is a 15-a-side attack-and-defend battleground off the southern coast of Northrend''s Dragonblight. The attacking team pilots siege engines and demolishers to smash through three walls of gates -- planting seaforium charges or ramming them down -- while defenders man turrets and cannons to hold them off, all racing a countdown clock that resets when a gate falls. If the attackers breach the final gate and detonate the relic at the citadel''s core, the two teams swap roles for a second round, and whichever side broke through faster wins; a team that never breaches loses outright. It shipped with Wrath of the Lich King at launch and opens to characters at level 71.', 'strand of the ancients,sota,siege engine,demolisher,seaforium,relic,dragonblight', 'pvp,battlegrounds,endgame,vehicles');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('bg_isle_of_conquest', 'Isle of Conquest', 'Isle of Conquest is a 40-a-side siege battleground on a Northrend island, added in patch 3.2. Both teams start by fighting over the Docks, Hangar, and Workshop, which unlock siege vehicles and an airship drop onto the enemy keep, while the Refinery and Quarry generate resources that fund reinforcements and boost siege damage. A team wins by breaching the enemy keep and killing its general -- Overlord Agmar for the Horde, Justicar Mariel Trueheart for the Alliance -- or by grinding the other side''s reinforcement count to zero first. Alongside Strand of the Ancients, it is one of the two Wrath-era battlegrounds built around vehicle combat, and it opens to characters at level 71.', 'isle of conquest,ioc,overlord agmar,justicar mariel trueheart,siege vehicles,reinforcements,workshop,hangar', 'pvp,battlegrounds,endgame,vehicles');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_ingvar_the_plunderer', 'Ingvar the Plunderer', 'Ingvar the Plunderer is the final boss of Utgarde Keep, a level 69 to 72 five-player dungeon in Howling Fjord. He is resurrected once by a val''kyr after the first kill, so the fight is effectively two rounds.', 'ingvar the plunderer,utgarde keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_prince_keleseth', 'Prince Keleseth', 'Prince Keleseth is the first boss of Utgarde Keep, a level 69 to 72 five-player dungeon in Howling Fjord. He freezes a player in an ice tomb that the rest of the group has to break.', 'prince keleseth,utgarde keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_keristrasza', 'Keristrasza', 'Keristrasza is the final boss of The Nexus, a level 71 to 73 five-player dungeon in Coldarra, in the Borean Tundra. She applies a stacking chill that forces the group to keep moving for the whole fight.', 'keristrasza,the nexus', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_grand_magus_telestra', 'Grand Magus Telestra', 'Grand Magus Telestra is a boss of The Nexus, a level 71 to 73 five-player dungeon in Coldarra, in the Borean Tundra. She splits into three copies partway through, each with a different school of magic.', 'grand magus telestra,the nexus', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_anub_arak', 'Anub''arak', 'Anub''arak is the final boss of Azjol-Nerub, a level 72 to 74 five-player dungeon in Dragonblight. He is the last nerubian king, raised by the Scourge; he also appears as the final encounter of Trial of the Crusader.', 'anub''arak,azjol-nerub', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_hadronox', 'Hadronox', 'Hadronox is the second boss of Azjol-Nerub, a level 72 to 74 five-player dungeon in Dragonblight. The fight is a fighting retreat up a web tunnel while she drags the party''s own pursuers into it.', 'hadronox,azjol-nerub', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_krik_thir_the_gatewatcher', 'Krik''thir the Gatewatcher', 'Krik''thir the Gatewatcher is the first boss of Azjol-Nerub, a level 72 to 74 five-player dungeon in Dragonblight. He is guarded by three named watchers that can be pulled with him.', 'krik''thir the gatewatcher,azjol-nerub', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_herald_volazj', 'Herald Volazj', 'Herald Volazj is the final boss of Ahn''kahet: The Old Kingdom, a level 73 to 75 five-player dungeon in Dragonblight. He casts an insanity effect that puts each player in a private phase fighting shadow copies of the group.', 'herald volazj,ahn''kahet: the old kingdom', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_prince_taldaram', 'Prince Taldaram', 'Prince Taldaram is a boss of Ahn''kahet: The Old Kingdom, a level 73 to 75 five-player dungeon in Dragonblight. He is a san''layn vampire who vanishes and embraces a player for heavy damage until two nearby orbs are clicked.', 'prince taldaram,ahn''kahet: the old kingdom', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_elder_nadox', 'Elder Nadox', 'Elder Nadox is the first boss of Ahn''kahet: The Old Kingdom, a level 73 to 75 five-player dungeon in Dragonblight. He summons swarms of adds, and one guardian must be killed fast or he becomes immune.', 'elder nadox,ahn''kahet: the old kingdom', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_king_dred', 'King Dred', 'King Dred is the final boss of Drak''Tharon Keep, a level 74 to 76 five-player dungeon in on the border between the Grizzly Hills and Zul''Drak. He is a devilsaur kept by the Drakkari, and the raptors around him can be pulled in with the fight.', 'king dred,drak''tharon keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_novos_the_summoner', 'Novos the Summoner', 'Novos the Summoner is the second boss of Drak''Tharon Keep, a level 74 to 76 five-player dungeon in on the border between the Grizzly Hills and Zul''Drak. He is untouchable until four channelling crystals around the platform are destroyed.', 'novos the summoner,drak''tharon keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_cyanigosa', 'Cyanigosa', 'Cyanigosa is the final boss of Violet Hold, a level 75 to 77 five-player dungeon in Dalaran. She arrives after the timed prison waves are survived, and is always the last encounter regardless of which mini-bosses spawned.', 'cyanigosa,violet hold', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_gal_darah', 'Gal''darah', 'Gal''darah is the final boss of Gundrak, a level 76 to 78 five-player dungeon in Zul''Drak. He shifts between troll and rhino form, impaling players in one and goring in the other.', 'gal''darah,gundrak', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_moorabi', 'Moorabi', 'Moorabi is a boss of Gundrak, a level 76 to 78 five-player dungeon in Zul''Drak. He tries to transform into a mammoth, which has to be interrupted or the fight gets much harder.', 'moorabi,gundrak', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_sjonnir_the_ironshaper', 'Sjonnir The Ironshaper', 'Sjonnir The Ironshaper is the final boss of Halls of Stone, a level 77 to 79 five-player dungeon in The Storm Peaks. He is reached after the Tribunal of Ages escort, and floods the room with iron and earthen adds.', 'sjonnir the ironshaper,halls of stone', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_maiden_of_grief', 'Maiden of Grief', 'Maiden of Grief is a boss of Halls of Stone, a level 77 to 79 five-player dungeon in The Storm Peaks. She drops shadow pools that have to be moved out of quickly.', 'maiden of grief,halls of stone', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_loken', 'Loken', 'Loken is the final boss of Halls of Lightning, a level 79 to 80 five-player dungeon in The Storm Peaks. The fight is a damage race against Lightning Nova and a pulse that hits harder the further away you stand.', 'loken,halls of lightning', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_general_bjarngrim', 'General Bjarngrim', 'General Bjarngrim is the first boss of Halls of Lightning, a level 79 to 80 five-player dungeon in The Storm Peaks. He patrols with an escort and cycles through three combat stances.', 'general bjarngrim,halls of lightning', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_king_ymiron', 'King Ymiron', 'King Ymiron is the final boss of Utgarde Pinnacle, a level 79 to 80 five-player dungeon in Howling Fjord. He is the vrykul king, and he channels power from the burial barrows around the room.', 'king ymiron,utgarde pinnacle', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_skadi_the_ruthless', 'Skadi the Ruthless', 'Skadi the Ruthless is a boss of Utgarde Pinnacle, a level 79 to 80 five-player dungeon in Howling Fjord. The first half is fought from a drake, throwing harpoons at his mount before he lands.', 'skadi the ruthless,utgarde pinnacle', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_svala_sorrowgrave', 'Svala Sorrowgrave', 'Svala Sorrowgrave is the first boss of Utgarde Pinnacle, a level 79 to 80 five-player dungeon in Howling Fjord. She sacrifices a player on an altar partway through and must be interrupted or healed past it.', 'svala sorrowgrave,utgarde pinnacle', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_ley_guardian_eregos', 'Ley-Guardian Eregos', 'Ley-Guardian Eregos is the final boss of The Oculus, a level 79 to 80 five-player dungeon in Coldarra, in the Borean Tundra. He is fought entirely from drake mounts, which is why the dungeon has the reputation it does.', 'ley-guardian eregos,the oculus', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_mal_ganis', 'Mal''Ganis', 'Mal''Ganis is the final boss of The Culling of Stratholme, a level 79 to 80 five-player dungeon in the Caverns of Time in Tanaris. He is the dreadlord who baits Arthas into the purge, and he escapes rather than dying.', 'mal''ganis,the culling of stratholme', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_chrono_lord_epoch', 'Chrono-Lord Epoch', 'Chrono-Lord Epoch is a boss of The Culling of Stratholme, a level 79 to 80 five-player dungeon in the Caverns of Time in Tanaris. He is an infinite dragonflight agent trying to stop the purge from happening as it should.', 'chrono-lord epoch,the culling of stratholme', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_the_black_knight', 'The Black Knight', 'The Black Knight is the final boss of Trial of the Champion, a level 79 to 80 five-player dungeon in the Argent Tournament grounds in Icecrown. He rises twice after being killed, first as a skeleton and then as a ghost.', 'the black knight,trial of the champion', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_devourer_of_souls', 'Devourer of Souls', 'Devourer of Souls is the final boss of The Forge of Souls, a level 79 to 80 five-player dungeon in Icecrown Citadel. It is a three-faced construct that alternates a mirrored fear with a wailing beam.', 'devourer of souls,the forge of souls', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_bronjahm', 'Bronjahm', 'Bronjahm is the first boss of The Forge of Souls, a level 79 to 80 five-player dungeon in Icecrown Citadel. He is the Godfather of Souls, and at thirty percent health he stops and channels while soul fragments close on him.', 'bronjahm,the forge of souls', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_scourgelord_tyrannus', 'Scourgelord Tyrannus', 'Scourgelord Tyrannus is the final boss of Pit of Saron, a level 79 to 80 five-player dungeon in Icecrown Citadel. He is fought at the end of the scripted escape, after his frost wyrm Rimefang harries the group up the ramp.', 'scourgelord tyrannus,pit of saron', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_forgemaster_garfrost', 'Forgemaster Garfrost', 'Forgemaster Garfrost is the first boss of Pit of Saron, a level 79 to 80 five-player dungeon in Icecrown Citadel. He forges a weapon mid-fight, changing his abilities each time he picks a new one up.', 'forgemaster garfrost,pit of saron', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_falric', 'Falric', 'Falric is the first boss of Halls of Reflection, a level 79 to 80 five-player dungeon in Icecrown Citadel. He appears after a set of scripted waves, and applies a stacking fear that grows through the fight.', 'falric,halls of reflection', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_marwyn', 'Marwyn', 'Marwyn is the second boss of Halls of Reflection, a level 79 to 80 five-player dungeon in Icecrown Citadel. He is the second of the two captains fought before the Lich King chase begins.', 'marwyn,halls of reflection', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_kel_thuzad', 'Kel''Thuzad', 'Kel''Thuzad is the final boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. He is the lich who founded the Scourge''s Cult of the Damned, fought at the top of the necropolis after Sapphiron.', 'kel''thuzad,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_sapphiron', 'Sapphiron', 'Sapphiron is the boss before Kel''Thuzad of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. A frost wyrm fought in an ice-covered room where players hide behind ice blocks to survive its breath.', 'sapphiron,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_patchwerk', 'Patchwerk', 'Patchwerk is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. A pure damage-and-healing check with no mechanics to speak of, long used as a benchmark fight.', 'patchwerk,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_thaddius', 'Thaddius', 'Thaddius is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. Players are given positive or negative charges and have to split by sign or take heavy raid damage.', 'thaddius,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_heigan_the_unclean', 'Heigan the Unclean', 'Heigan the Unclean is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. Known for its dance: the floor erupts in a repeating pattern the whole raid has to keep ahead of.', 'heigan the unclean,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_loatheb', 'Loatheb', 'Loatheb is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. Healing is blocked except in brief windows, so healers rotate through a fixed order.', 'loatheb,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_instructor_razuvious', 'Instructor Razuvious', 'Instructor Razuvious is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. He is tanked by mind-controlled understudies rather than by a player.', 'instructor razuvious,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_maexxna', 'Maexxna', 'Maexxna is a boss of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. She webs players to the wall, and the rest of the raid has to free them.', 'maexxna,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_anub_rekhan', 'Anub''Rekhan', 'Anub''Rekhan is the first boss of the Arachnid Quarter of Naxxramas, a level 80 ten- and twenty-five-player raid in Dragonblight. He is a nerubian crypt lord who summons corpse scarabs while chasing a random player.', 'anub''rekhan,naxxramas', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_sartharion', 'Sartharion', 'Sartharion is the final boss of The Obsidian Sanctum, a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. Leaving his three drakes alive when he is pulled raises the difficulty and the reward.', 'sartharion,the obsidian sanctum', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_malygos', 'Malygos', 'Malygos is the final boss of The Eye of Eternity, a level 80 ten- and twenty-five-player raid in Coldarra, in the Borean Tundra. The Aspect of Magic, and the fight ends with the whole raid on drakes in a vehicle phase.', 'malygos,the eye of eternity', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_yogg_saron', 'Yogg-Saron', 'Yogg-Saron is the final boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. An Old God fought in three phases, including a stretch inside visions of the past; leaving fewer of Sara''s keepers active makes it much harder.', 'yogg-saron,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_flame_leviathan', 'Flame Leviathan', 'Flame Leviathan is the first boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. The entire fight is fought from siege vehicles rather than on foot.', 'flame leviathan,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_mimiron', 'Mimiron', 'Mimiron is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. A four-phase mechanical fight, and its hard mode sets the room on fire for the duration.', 'mimiron,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_thorim', 'Thorim', 'Thorim is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. The raid splits in two, one group through an arena gauntlet and one up a corridor, meeting at the top.', 'thorim,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_freya', 'Freya', 'Freya is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. Her hard mode is set by leaving up to three elders alive when she is pulled.', 'freya,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_kologarn', 'Kologarn', 'Kologarn is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. A giant built into the wall, whose two arms are killed separately and regrow.', 'kologarn,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_xt_002_deconstructor', 'XT-002 Deconstructor', 'XT-002 Deconstructor is a boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. Its heart is exposed periodically, and attacking it there is what triggers the hard mode.', 'xt-002 deconstructor,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_algalon_the_observer', 'Algalon the Observer', 'Algalon the Observer is a bonus boss of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. A limited-attempt encounter behind a hard-mode gate, added as the expansion''s most exclusive kill at the time.', 'algalon the observer,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_general_vezax', 'General Vezax', 'General Vezax is the boss before Yogg-Saron of Ulduar, a level 80 ten- and twenty-five-player raid in The Storm Peaks. Mana regeneration is shut off for the fight, so casters draw from saronite vapours instead.', 'general vezax,ulduar', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_lord_jaraxxus', 'Lord Jaraxxus', 'Lord Jaraxxus is a boss of Trial of the Crusader, a level 80 ten- and twenty-five-player raid in the Argent Tournament grounds in Icecrown. An eredar lord accidentally summoned into the arena partway through the event.', 'lord jaraxxus,trial of the crusader', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_the_lich_king', 'The Lich King', 'The Lich King is the final boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. Arthas Menethil, fought on the roof of the Frozen Throne; it is the last encounter of Wrath of the Lich King. He also appears unkillable at the end of Halls of Reflection.', 'the lich king,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_sindragosa', 'Sindragosa', 'Sindragosa is the boss before the Lich King of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. Sapphiron''s risen mate, who stacks a frost debuff that forces players to hide behind ice tombs.', 'sindragosa,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_professor_putricide', 'Professor Putricide', 'Professor Putricide is a boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. The end of the plague wing, fought around slime pools he brews mid-fight.', 'professor putricide,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_lord_marrowgar', 'Lord Marrowgar', 'Lord Marrowgar is the first boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. He impales players on bone spikes and whirlwinds across the room.', 'lord marrowgar,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_deathbringer_saurfang', 'Deathbringer Saurfang', 'Deathbringer Saurfang is a boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. He gains power from blood drawn off the raid, so damage taken is what fuels him.', 'deathbringer saurfang,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_lady_deathwhisper', 'Lady Deathwhisper', 'Lady Deathwhisper is the second boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. She is shielded by mana until it is burned through, and raises adds from the cultists around her.', 'lady deathwhisper,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_blood_queen_lana_thel', 'Blood-Queen Lana''thel', 'Blood-Queen Lana''thel is a boss of Icecrown Citadel, a level 80 ten- and twenty-five-player raid in Icecrown. She bites a player who must pass the bite on before a timer, spreading it through the raid.', 'blood-queen lana''thel,icecrown citadel', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_halion', 'Halion', 'Halion is the final boss of The Ruby Sanctum, a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. He is fought in a physical and a shadow version of the same room at once, with the raid split between them.', 'halion,the ruby sanctum', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_archavon_the_stone_watcher', 'Archavon the Stone Watcher', 'Archavon the Stone Watcher is the first boss of Vault of Archavon, a level 80 ten- and twenty-five-player raid in Wintergrasp. He is only reachable by the faction that currently holds Wintergrasp.', 'archavon the stone watcher,vault of archavon', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_onyxia', 'Onyxia', 'Onyxia is the only boss of Onyxia''s Lair, a level 80 ten- and twenty-five-player raid in Dustwallow Marsh. A black dragon fought in ground and air phases; retuned from level 60 to level 80 in patch 3.2.2.', 'onyxia,onyxia''s lair', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_ragnaros', 'Ragnaros', 'Ragnaros is the final boss of Molten Core, a level 60 to 63 forty-player raid in Blackrock Mountain. A firelord summoned by the Dark Iron dwarves, and the game''s first raid-ending boss.', 'ragnaros,molten core', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_nefarian', 'Nefarian', 'Nefarian is the final boss of Blackwing Lair, a level 60 to 63 forty-player raid in Blackrock Mountain. Deathwing''s son, who calls out class-wide effects by name during the fight.', 'nefarian,blackwing lair', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_hakkar', 'Hakkar', 'Hakkar is the final boss of Zul''Gurub, a level 57 to 63 twenty-player raid in Stranglethorn Vale. The blood god of the Gurubashi trolls, weakened by killing his high priests first.', 'hakkar,zul''gurub', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_c_thun', 'C''Thun', 'C''Thun is the final boss of Ahn''Qiraj Temple, a level 60 to 63 forty-player raid in Silithus. An Old God fought partly from inside its own stomach.', 'c''thun,ahn''qiraj temple', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_edwin_vancleef', 'Edwin VanCleef', 'Edwin VanCleef is the final boss of Deadmines, a level 17 to 20 five-player dungeon in Westfall. The leader of the Defias Brotherhood, fought on the deck of a ship inside the mine.', 'edwin vancleef,deadmines', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_archmage_arugal', 'Archmage Arugal', 'Archmage Arugal is the final boss of Shadowfang Keep, a level 18 to 21 five-player dungeon in Silverpine Forest. The renegade mage who created the worgen infesting the keep.', 'archmage arugal,shadowfang keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_baron_rivendare', 'Baron Rivendare', 'Baron Rivendare is the final boss of the undead side of Stratholme, a level 58 to 60 five-player dungeon in the Eastern Plaguelands. He drops the Deathcharger''s Reins, and a timed run of his wing rewards extra loot.', 'baron rivendare,stratholme', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_darkmaster_gandling', 'Darkmaster Gandling', 'Darkmaster Gandling is the final boss of Scholomance, a level 58 to 60 five-player dungeon in the Western Plaguelands. The headmaster of the necromancy school, who teleports players into side rooms during the fight.', 'darkmaster gandling,scholomance', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_emperor_dagran_thaurissan', 'Emperor Dagran Thaurissan', 'Emperor Dagran Thaurissan is the final boss of Blackrock Depths, a level 49 to 56 five-player dungeon in Blackrock Mountain. The Dark Iron emperor, fought beside his wife Moira, who must be left alive.', 'emperor dagran thaurissan,blackrock depths', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_illidan_stormrage', 'Illidan Stormrage', 'Illidan Stormrage is the final boss of Black Temple, a level 70 twenty-five-player raid in Shadowmoon Valley. The Betrayer, and the intended final boss of the Burning Crusade before the Sunwell was added.', 'illidan stormrage,black temple', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_kael_thas_sunstrider', 'Kael''thas Sunstrider', 'Kael''thas Sunstrider is the final boss of Tempest Keep, a level 70 twenty-five-player raid in Netherstorm. The blood elf prince, fought in a long multi-phase encounter; a weakened version of him is also the final boss of Magister''s Terrace.', 'kael''thas sunstrider,tempest keep', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_lady_vashj', 'Lady Vashj', 'Lady Vashj is the final boss of Coilfang: Serpentshrine Cavern, a level 70 twenty-five-player raid in Zangarmarsh. A naga sea witch whose middle phase requires relaying tainted cores to break her shield.', 'lady vashj,coilfang: serpentshrine cavern', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_kil_jaeden', 'Kil''jaeden', 'Kil''jaeden is the final boss of The Sunwell, a level 70 twenty-five-player raid in the Isle of Quel''Danas. The Burning Legion''s second-in-command, and the last boss of the Burning Crusade.', 'kil''jaeden,the sunwell', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_archimonde', 'Archimonde', 'Archimonde is the final boss of The Battle for Mount Hyjal, a level 70 twenty-five-player raid in the Caverns of Time in Tanaris. Fought at the World Tree, where players use tears of the goddess to survive his air burst.', 'archimonde,the battle for mount hyjal', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_prince_malchezaar', 'Prince Malchezaar', 'Prince Malchezaar is the final boss of Karazhan, a level 70 to 73 ten-player raid in Deadwind Pass. A eredar prince at the top of the tower, who rains infernals into the room.', 'prince malchezaar,karazhan', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_gruul_the_dragonkiller', 'Gruul the Dragonkiller', 'Gruul the Dragonkiller is the final boss of Gruul''s Lair, a level 70 twenty-five-player raid in Blade''s Edge Mountains. He grows larger and hits harder on a timer, so the raid spreads out to avoid shatter damage.', 'gruul the dragonkiller,gruul''s lair', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_magtheridon', 'Magtheridon', 'Magtheridon is the only boss of Magtheridon''s Lair, a level 70 twenty-five-player raid in Hellfire Peninsula. A pit lord held in place by five channelers who must be killed together.', 'magtheridon,magtheridon''s lair', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_zul_jin', 'Zul''jin', 'Zul''jin is the final boss of Zul''Aman, a level 70 to 73 ten-player raid in the Ghostlands. The Amani warlord, who cycles through animal-god forms as his health drops.', 'zul''jin,zul''aman', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_mekgineer_thermaplugg', 'Mekgineer Thermaplugg', 'Mekgineer Thermaplugg is the final boss of Gnomeregan, a level 25 to 28 five-player dungeon in Dun Morogh. He is fought around a room of bomb-dispensing panels that have to be closed.', 'mekgineer thermaplugg,gnomeregan', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_archaedas', 'Archaedas', 'Archaedas is the final boss of Uldaman, a level 37 to 40 five-player dungeon in the Badlands. A titan construct who animates the statues lining the room as adds.', 'archaedas,uldaman', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_murmur', 'Murmur', 'Murmur is the final boss of Auchindoun: Shadow Labyrinth, a level 69 to 70 five-player dungeon in Terokkar Forest. A sound elemental with a room-wide pull followed by a detonation players must run out of.', 'murmur,auchindoun: shadow labyrinth', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_chief_ukorz_sandscalp', 'Chief Ukorz Sandscalp', 'Chief Ukorz Sandscalp is the final boss of Zul''Farrak, a level 43 to 46 five-player dungeon in Tanaris. The Sandfury chief, reached after the pyramid steps event.', 'chief ukorz sandscalp,zul''farrak', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_princess_theradras', 'Princess Theradras', 'Princess Theradras is the final boss of Maraudon, a level 41 to 48 five-player dungeon in Desolace. An earth elemental princess at the bottom of the pristine waters wing.', 'princess theradras,maraudon', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_king_gordok', 'King Gordok', 'King Gordok is the final boss of the north wing of Dire Maul, a level 55 to 60 five-player dungeon in Feralas. Killing him grants the ogre suit tribute run, which is why players clear the wing carefully.', 'king gordok,dire maul', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_general_drakkisath', 'General Drakkisath', 'General Drakkisath is the final boss of the upper wing of Blackrock Spire, a level 57 to 63 five- and ten-player dungeon in Blackrock Mountain. He guards the orb used for the old Onyxia attunement chain.', 'general drakkisath,blackrock spire', 'boss,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_mutanus_the_devourer', 'Mutanus the Devourer', 'Mutanus the Devourer is the final boss of Wailing Caverns, a level 17 to 20 five-player dungeon in the Barrens. He appears at the end of the escort event that the whole dungeon leads up to.', 'mutanus the devourer,wailing caverns', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_amnennar_the_coldbringer', 'Amnennar the Coldbringer', 'Amnennar the Coldbringer is the final boss of Razorfen Downs, a level 34 to 37 five-player dungeon in the Southern Barrens. A lich raising the quilboar dead, and the highest-level threat in the warrens.', 'amnennar the coldbringer,razorfen downs', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_herod', 'Herod', 'Herod is the final boss of the Armory wing of Scarlet Monastery, a level 29 to 40 five-player dungeon in Tirisfal Glades. The Scarlet champion, who whirlwinds across the room and then flees to pull the training hall.', 'herod,scarlet monastery', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('boss_high_inquisitor_whitemane', 'High Inquisitor Whitemane', 'High Inquisitor Whitemane is the final boss of the Cathedral wing of Scarlet Monastery, a level 29 to 40 five-player dungeon in Tirisfal Glades. She resurrects Scarlet Commander Mograine once, so both have to be brought down together.', 'high inquisitor whitemane,scarlet monastery', 'boss,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_rules_general', 'Capital Cities', 'Capital cities are safe hubs, not leveling ground. They contain no hostile mobs to kill and no quest grinding areas. Dueling is disabled inside city limits, so players who want to duel step outside the gates first. Every capital has a bank, auction house, mailbox, inn with an innkeeper for setting your hearthstone, flight master, stable master, guild master, barber shop, and the full set of class and profession trainers. Resting in a city accumulates rested experience faster than resting in the wild.', 'capital,capital city,city,cities,safe,no mobs,cannot duel,dueling disabled,duel,hub,rested experience,barber shop,city limits', 'city,mechanics,safe_zone');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_stormwind', 'Stormwind City', 'Stormwind City is the human capital and the main Alliance hub in the Eastern Kingdoms, sitting in the north of Elwynn Forest. It is divided into the Trade District, Old Town, the Mage Quarter, Cathedral Square, the Dwarven District, and the Park, with the Valley of Heroes at the front gates. King Varian Wrynn rules from Stormwind Keep. The Deeprun Tram runs underground from the Dwarven District to Ironforge, and the harbor carries boats to Northrend and Kalimdor.', 'stormwind,stormwind city,human capital,alliance capital,trade district,old town,mage quarter,cathedral square,dwarven district,valley of heroes,stormwind keep,varian wrynn,deeprun tram,stormwind harbor', 'city,alliance,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_ironforge', 'Ironforge', 'Ironforge is the dwarven capital, carved into the mountain of Dun Morogh and centered on the Great Forge. Its districts include the Commons, Tinker Town, the Mystic Ward, the Military Ward, and the Hall of Explorers, which houses the Explorers'' League and the museum. King Magni Bronzebeard rules here. The Deeprun Tram connects Ironforge to Stormwind, and the gryphon roost handles Alliance flight paths across the Eastern Kingdoms.', 'ironforge,dwarven capital,dwarf capital,great forge,tinker town,mystic ward,military ward,hall of explorers,explorers league,magni bronzebeard,deeprun tram,gryphon roost', 'city,alliance,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_darnassus', 'Darnassus', 'Darnassus is the night elf capital, built among the branches of Teldrassil across the sea in northern Kalimdor. Its districts include the Temple of the Moon, the Cenarion Enclave, the Craftsmen''s Terrace, the Warrior''s Terrace, and the Tradesmen''s Terrace. High Priestess Tyrande Whisperwind leads from the temple. Players reach it through the portal at Rut''theran Village at the base of the tree, which also connects by boat to Darkshore and Azuremyst Isle.', 'darnassus,night elf capital,temple of the moon,cenarion enclave,craftsmens terrace,warriors terrace,tyrande whisperwind,rutheran village,teldrassil capital', 'city,alliance,kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_exodar', 'The Exodar', 'The Exodar is the draenei capital, a crashed naaru vessel embedded in the western edge of Azuremyst Isle off the coast of Kalimdor. Its wings include the Trader''s Tier, the Crystal Hall, the Vault of Lights, and the Seat of the Naaru, where Prophet Velen resides. It is the least-trafficked Alliance capital, and a boat from Azuremyst Isle connects it to Darnassus and the rest of Kalimdor.', 'exodar,the exodar,draenei capital,traders tier,crystal hall,vault of lights,seat of the naaru,velen,prophet velen,azuremyst capital', 'city,alliance,kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_orgrimmar', 'Orgrimmar', 'Orgrimmar is the orc capital and the main Horde hub, built into the canyons of Durotar. Its districts are the Valley of Strength, the Valley of Honor, the Valley of Wisdom, the Valley of Spirits, the Drag, and the Cleft of Shadow, where warlocks and rogues train and the entrance to Ragefire Chasm sits. Warchief Thrall rules from Grommash Hold. Zeppelin towers outside the gates run to Undercity, Grom''gol in Stranglethorn, and Northrend.', 'orgrimmar,orc capital,horde capital,valley of strength,valley of honor,valley of wisdom,valley of spirits,cleft of shadow,the drag,grommash hold,thrall,warchief,zeppelin tower', 'city,horde,kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_thunder_bluff', 'Thunder Bluff', 'Thunder Bluff is the tauren capital, a cluster of mesas rising above the plains of Mulgore and joined by rope bridges and wooden elevators. Elder Rise, Spirit Rise, and Hunter Rise ring the central High Rise, where Cairne Bloodhoof leads. It is the Horde''s center for shamanism, druidism, and leatherworking, and the long fall from its bridges is a hazard for players who miss the lift.', 'thunder bluff,tauren capital,mulgore capital,elder rise,spirit rise,hunter rise,high rise,cairne bloodhoof,mesa,rope bridges,elevators', 'city,horde,kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_undercity', 'Undercity', 'Undercity is the Forsaken capital, built in the catacombs beneath the ruined city of Lordaeron in Tirisfal Glades. It is laid out as a ring of quarters around a central well: the Trade Quarter, the War Quarter, the Magic Quarter, the Rogues'' Quarter, and the Apothecarium, where Lady Sylvanas Windrunner and the Royal Apothecary Society plot. A zeppelin tower outside the ruins connects it to Orgrimmar and Northrend.', 'undercity,forsaken capital,undead capital,lordaeron,ruins of lordaeron,trade quarter,war quarter,magic quarter,rogues quarter,apothecarium,sylvanas windrunner,royal apothecary society', 'city,horde,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_silvermoon', 'Silvermoon City', 'Silvermoon City is the blood elf capital in northern Eversong Woods, the last great city of Quel''Thalas. Its districts include the Royal Exchange, the Bazaar, the Walk of Elders, and Sunfury Spire, where Lor''themar Theron rules as regent. It is the most remote Horde capital: players usually arrive through the orb of translocation linking Undercity to Silvermoon, rather than travelling overland through the Ghostlands.', 'silvermoon,silvermoon city,blood elf capital,quelthalas,royal exchange,the bazaar,walk of elders,sunfury spire,lorthemar theron,orb of translocation', 'city,horde,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_shattrath', 'Shattrath City', 'Shattrath City is the neutral hub of Outland, in western Terokkar Forest, where both factions trade and quest side by side. It is a sanctuary: all player versus player combat is disabled inside, including dueling. The Terrace of Light holds the naaru A''dal and portals to every capital city, while the Lower City below is home to refugees and the Sha''tar''s quartermasters. Players choose between the Aldor and the Scryers here, and the choice locks out the other faction''s rewards.', 'shattrath,shattrath city,outland hub,neutral city,sanctuary,no pvp,terrace of light,lower city,adal,the shatar,aldor,scryers,terokkar', 'city,neutral,outland,sanctuary');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('city_dalaran', 'Dalaran', 'Dalaran is the neutral magical city of Northrend, floating above Crystalsong Forest, and the main hub for level 75 and above. Like Shattrath it is a sanctuary, so faction combat and dueling are disabled in the streets above. Runeweaver Square holds portals to every capital, and the Violet Citadel houses the Kirin Tor under Rhonin. The exception is the Underbelly, the sewer level beneath the city, where free-for-all combat is allowed and players do fight.', 'dalaran,northrend hub,floating city,neutral city,sanctuary,kirin tor,runeweaver square,violet citadel,rhonin,the underbelly,dalaran sewers,crystalsong forest', 'city,neutral,northrend,sanctuary');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_warrior', 'Warrior Class', 'Warriors are versatile melee fighters who excel in both damage dealing and tanking. They have three specializations: Arms (melee DPS), Fury (two-handed weapon DPS), and Protection (tanking). Warriors use rage as their resource and can charge into battle, use defensive stances, and provide strong physical damage. They are essential for tanking dungeons and raids.', 'warrior,tank,dps,melee,rage,arms,fury,protection,battle,stances,versatile,fighter,combat,strength,damage,protection,shield,sword,axe,mace,charge,intercept,taunt,challenging shout', 'class,melee,tank,dps,versatile');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_paladin', 'Paladin Class', 'Paladins are holy warriors who combine melee combat with divine magic. They can be healers (Holy), melee DPS (Retribution), or tanks (Protection). Paladins use mana for spells and holy power for special abilities. They have strong utility with blessings, auras, and can protect allies with divine shields. Paladins are highly valued for their healing and tanking in groups.', 'paladin,healer,tank,dps,holy,retribution,protection,divine', 'class,hybrid,healer,tank,dps');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_hunter', 'Hunter Class', 'Hunters are ranged DPS specialists who use bows, guns, or crossbows to deal damage from afar. They have pets that fight alongside them and can track enemies, trap them, and provide utility. Hunters excel at solo play and can handle multiple targets effectively. They use focus as their resource and have strong survival abilities.', 'hunter,ranged,dps,pets,tracking,traps,focus', 'class,ranged,dps,pets,utility');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_rogue', 'Rogue Class', 'Rogues are stealthy melee DPS specialists who excel at burst damage and controlling the battlefield. They can stealth, pick locks, and assassinate targets. Rogues have high mobility with abilities like sprint and vanish. They use energy as their resource and combo points to unleash powerful finishing moves. Rogues are deadly in PvP and excel at controlling fights.', 'rogue,stealth,melee,dps,burst,energy,combo points,assassinate,sprint,vanish,backstab,sap,kidney shot,eviscerate,sinister strike,pick lock,lockpicking,poison,dagger,leather armor,agility,critical strike,mobility', 'class,melee,dps,stealth,control');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_priest', 'Priest Class', 'Priests are versatile spellcasters who can be healers (Holy/Discpline) or ranged DPS (Shadow). They use holy magic for healing and shadow magic for damage. Priests have strong utility with mind control, fear, and resurrection. They can provide mana to others and have powerful area healing abilities. Priests are essential for keeping groups alive in tough encounters.', 'priest,healer,dps,holy,shadow,utility,resurrection', 'class,caster,healer,dps,utility');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_shaman', 'Shaman Class', 'Shamans are elemental spellcasters who can be healers (Restoration), melee DPS (Enhancement), or ranged DPS (Elemental). They call upon the power of elements and spirits. Shamans have totems that provide group buffs and can weapon imbue for different effects. They excel at area damage and healing, making them valuable in groups and raids.', 'shaman,healer,dps,elemental,totems,spirits,enhancement', 'class,hybrid,healer,dps,elemental');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_mage', 'Mage Class', 'Mages are powerful ranged spellcasters who deal massive damage with fire, frost, and arcane magic. They can polymorph enemies, teleport, and create portals. Mages have strong crowd control and can burst down targets quickly. They use mana as their resource and have abilities to conserve mana. Mages are glass cannons - high damage but low survivability.', 'mage,ranged,dps,fire,frost,arcane,polymorph,teleport', 'class,caster,ranged,dps,control');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_warlock', 'Warlock Class', 'Warlocks are dark spellcasters who make pacts with demons to gain power. They summon demonic pets and use curses, drains, and destructive spells. Warlocks can create soulstones, healthstones, and spellstones. They excel at sustained damage over time and have strong crowd control. Warlocks use mana and have demonic resources through their pacts.', 'warlock,caster,dps,demons,pets,curses,soulstone,summon,healthstone', 'class,caster,dps,demonic,control');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_druid', 'Druid Class', 'Druids are shapeshifting spellcasters who can be healers (Restoration), melee DPS (Feral), ranged DPS (Balance), or tanks (Guardian). They can transform into various animal forms for different roles. Druids have strong utility with crowd control, healing, and mobility. They are highly versatile and can adapt to different group needs.', 'druid,shapeshift,healer,tank,dps,feral,balance,restoration', 'class,hybrid,versatile,shapeshift');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_classes_death_knight', 'Death Knight Class', 'Death Knights are undead warriors raised by the Lich King, available starting in Wrath of the Lich King. They are powerful tanks (Blood) or DPS (Frost/Unholy) with rune-based abilities. Death Knights have strong survivability and can raise ghouls to assist in combat. They use runes and runic power as resources and have anti-magic abilities.', 'death knight,undead,tank,dps,runes,runic power,blood,frost,unholy,lich king,ghoul,anti magic,death grip,death coil,icy touch,plague strike,blood strike,frost strike,scourge strike,lichborne,antimagic shell,bone shield', 'class,melee,tank,dps,undead');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_factions_alliance', 'Alliance Faction', 'The Alliance is one of the two major factions in Azeroth, consisting of noble and honorable races united against the Horde. Member races include Humans, Dwarves, Gnomes, Night Elves, and Draenei. The Alliance values honor, tradition, and protecting Azeroth from threats. Their capital cities include Stormwind, Ironforge, Darnassus, and the Exodar. Alliance players work together to maintain peace and order.', 'alliance,faction,honor,tradition,humans,dwarves,gnomes,night_elves,draenei', 'faction,alliance,races,cities');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_factions_horde', 'Horde Faction', 'The Horde is a powerful faction of warrior races who fight for survival and strength. Member races include Orcs, Trolls, Tauren, Undead (Forsaken), and Blood Elves. The Horde values strength, honor in battle, and protecting their way of life. Their capital cities include Orgrimmar, Thunder Bluff, Undercity, and Silvermoon City. Horde players are fierce warriors who respect strength and combat prowess.', 'horde,faction,strength,warriors,orcs,trolls,tauren,undead,blood_elves,orgrimmar,thunder bluff,undercity,silvermoon,thrall,sylvanas,garrosh,voljin,baine bloodhoof,lor the mar,horde pride,red,black,for the horde', 'faction,horde,races,cities');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_humans', 'Human Race', 'Humans are the most widespread and adaptable race in Azeroth, known for their resilience and determination. They founded the Alliance and built the mighty kingdom of Stormwind. Humans excel at all classes and are known for their diplomacy and leadership. Key traits include the Human Spirit (+3% Spirit) and Diplomacy (+10% reputation gains with every faction). Humans start in Elwynn Forest and have access to mounts at level 20.', 'human,alliance,stormwind,diplomacy,leadership,resilience,determination,elwynn forest,king varian,anduin,bolvar,tirion fordring,spirit,reputation,versatile,paladin,warrior,rogue,mage,priest,warlock', 'race,alliance,human,versatile');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_orcs', 'Orc Race', 'Orcs are fierce and honorable warriors from Draenor, brought to Azeroth through the Dark Portal. They form the backbone of the Horde and value strength and combat prowess above all. Orcs have Command (+5% pet damage), Axe Specialization, Hardiness (reduced stun duration), and the activated Blood Fury racial. They start in Durotar and have a rich history of shamanism and warfare. Notable orcs include Thrall, Garrosh Hellscream, and Grommash Hellscream.', 'orc,horde,draenor,dark portal,strength,warriors,shaman,thrall,garrosh,grommash,durotar,orgrimmar,expertise,bloodlust,hardiness,axe thrower,warrior,hunter,shaman,rogue,death knight', 'race,horde,orc,warrior');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_dwarves', 'Dwarf Race', 'Dwarves are stout, bearded mountain dwellers known for their craftsmanship and love of ale. They are master miners, blacksmiths, and engineers. Dwarves have Gun Specialization, Mace Specialization, passive Frost Resistance, and the activated Stoneform racial, which cures poison, disease, and bleed effects. They start in Dun Morogh and are fiercely loyal to the Alliance. Dwarves excel at warrior, priest, and hunter classes. Famous dwarves include King Magni Bronzebeard and Muradin Bronzebeard.', 'dwarf,alliance,ironforge,craftsmanship,mining,blacksmithing,engineering,ale,beards,dun morogh,king magni,muradin,expertise,reputation,stoneform,gun specialization,warrior,priest,hunter,paladin,rogue', 'race,alliance,dwarf,craftsman');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_night_elves', 'Night Elf Race', 'Night Elves are ancient, immortal beings who protect the natural world of Azeroth. They are master druids, hunters, and warriors with a deep connection to nature. Night Elves have Quickness (+1% dodge), passive Nature Resistance, and Shadowmeld, an activated near-invisibility used while standing still; on death they briefly become a fast-moving wisp. They start on the sacred tree of Teldrassil and are devoted to Elune. Night Elves excel at druid, hunter, and priest classes. Key figures include Tyrande Whisperwind and Malfurion Stormrage.', 'night elf,alliance,nature,druid,hunter,immortal,elune,teldrassil,darnassus,tyrande,malfurion,nature resistance,wisp spirit,shadowmeld,quickness,druid,hunter,priest,warrior,rogue', 'race,alliance,night elf,nature');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_tauren', 'Tauren Race', 'Tauren are massive, peaceful nomads from the plains of Mulgore, devoted to the spirits of nature. They are natural shamans and druids with a deep spiritual connection to the elements. Tauren have +5% health and +5% nature resistance. They start in Mulgore and have a rich culture of storytelling and herbalism. Tauren excel at druid, shaman, and warrior classes. Chief Baine Bloodhoof leads the tauren people.', 'tauren,horde,mulgore,plains,shaman,druid,spirits,nature,thunder bluff,baine bloodhoof,health,nature resistance,cultivation,endurance,war stomp,druid,shaman,warrior,hunter,priest', 'race,horde,tauren,spiritual');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_trolls', 'Troll Race', 'Trolls are fierce jungle warriors from the islands of the South Seas, known for their regeneration and voodoo magic. They are agile hunters and warriors with a tribal culture. Trolls have Berserking (an activated haste burst that grows stronger as health drops), Regeneration (faster health regen that partly continues in combat), and Beast Slaying (+5% damage to Beasts). They start in Durotar alongside the orcs. Trolls excel at hunter, mage, priest, rogue, shaman, and warrior classes. Notable trolls include Vol''jin and Zul''jin.', 'troll,horde,jungle,warriors,regeneration,voodoo,hunter,durotar,voljin,zuljin,attack speed,expertise,beast slaying,berserking,da voodoo shuffle,hunter,mage,priest,rogue,shaman,warrior', 'race,horde,troll,agile');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_gnomes', 'Gnome Race', 'Gnomes are ingenious tinkerers and inventors from the underground city of Gnomeregan. They are brilliant engineers and mages with a love for technology. Gnomes have Expansive Mind (+5% intellect), a 2% reduced chance to be hit by arcane spells (Arcane Resistance), and Engineering Specialization (+15 engineering skill). They start in Dun Morogh and are loyal Alliance members. Gnomes excel at mage, rogue, and warrior classes. Famous gnomes include High Tinker Mekkatorque and Sicco Thermaplugg.', 'gnome,alliance,gnomeregan,tinkerers,engineers,technology,dun morogh,ironforge,mekkatorque,sicco,intellect,arcane resistance,escape artist,engineering specialization,mage,rogue,warrior,warlock,death knight', 'race,alliance,gnome,ingenious');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_forsaken', 'Forsaken (Undead) Race', 'The Forsaken are undead beings who broke free from the Scourge, fighting for their freedom. They are cunning rogues and warlocks with resistance to fear and sleep. Forsaken have Will of the Forsaken (removes fear, sleep, and charm effects), Cannibalize (health regen from nearby corpses), and passive Shadow Resistance. They start in Tirisfal Glades and rule the Undercity. Forsaken excel at rogue, warlock, priest, mage, and warrior classes. Queen Sylvanas Windrunner leads the Forsaken.', 'forsaken,undead,horde,scourge,freedom,undercity,tirisfal glades,sylvanas,expertise,shadow resistance,cannibalize,will of the forsaken,rogue,warlock,priest,mage,warrior', 'race,horde,undead,forsaken');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_blood_elves', 'Blood Elf Race', 'Blood Elves are magically addicted survivors of the fallen kingdom of Quel''Thalas. They are powerful mages and paladins with a thirst for magic. Blood Elves have Arcane Torrent (a silence that also restores mana, energy, runic power, or rage), Arcane Affinity (+10 Enchanting skill), and passive Magic Resistance. They start in Eversong Woods and are devoted to Kael''thas Sunstrider. Blood Elves excel at mage, paladin, priest, rogue, hunter, and warlock classes.', 'blood elf,horde,quel thalas,magic addiction,silvermoon,eversong woods,kaelthas,intellect,reputation,arcane torrent,mage,paladin,priest,rogue,hunter,warlock,death knight', 'race,horde,blood elf,magical');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('wow_races_draenei', 'Draenei Race', 'Draenei are a tailed, hooved alien race who crashed on Azeroth fleeing demonic pursuers. They are holy paladins and priests with a devotion to the Light. Draenei have Heroic Presence (+1% hit chance for themselves and their party), Gift of the Naaru (an activated heal-over-time), and Gemcutting (+5 Jewelcrafting skill). They start on Azuremyst Isle and have advanced technology. Draenei excel at paladin, priest, shaman, mage, hunter, and warrior classes. Prophet Velen leads the draenei.', 'draenei,alliance,exodar,azuremyst isle,light,paladin,priest,velen,strength,reputation,heroic presence,gift of the naaru,paladin,priest,shaman,mage,hunter,warrior', 'race,alliance,draenei,holy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_leveling_guide', 'Leveling Strategies', 'Efficient leveling involves questing in appropriate level zones, using rest bonuses, and grouping when possible. Follow zone storylines for better experience. Use flight paths to travel efficiently. Complete dungeons for bonus experience. Leveling speed depends on playstyle and available time. Some classes level faster than others due to mechanics.', 'leveling,questing,rest bonus,grouping,dungeons,experience,zone storylines,flight paths,travel,bonus experience,playstyle,time,classes,mechanics,efficient,speed', 'general,leveling,progression,efficiency');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_gold_making', 'Gold Making Methods', 'Gold can be made through professions, auction house trading, farming rare mobs, completing quests, and running dungeons. Blacksmithing and enchanting are profitable. Understanding market demand is key. Some methods require significant time investment. Gold is used for mounts, repairs, and training.', 'gold making,professions,auction house,farming,trading,market,blacksmithing,enchanting,profitable,demand,time investment,mounts,repairs,training,rare mobs,quests,dungeons', 'general,economy,gold,professions');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_ui_customization', 'Interface Customization', 'The UI can be customized extensively. Move frames, change sizes, add custom addons. Key bindings improve efficiency. Action bars can be configured for different situations. Understanding the interface is crucial for effective play. Many players use custom UI setups for optimal performance.', 'ui customization,frames,addons,key bindings,action bars,efficiency,interface,custom,performance,move frames,change sizes,configured,effective play,custom ui', 'general,interface,customization,addons');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_addons', 'Essential Addons', 'Popular addons include Deadly Boss Mods for raid encounters, QuestHelper for navigation, Gatherer for resource tracking, and Auctioneer for auction house management. Addons enhance gameplay but must be kept updated. Some addons provide quality of life improvements. Choosing the right addons depends on playstyle.', 'addons,deadly boss mods,questhelper,gatherer,auctioneer,quality of life,raid encounters,navigation,resource tracking,auction house,updated,enhance gameplay,playstyle', 'general,addons,tools,enhancement');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_server_population', 'Server Types and Population', 'Servers have different populations and rulesets. PvP servers allow open world combat, PvE servers restrict PvP. High population servers have active economies, low population servers have empty cities. Server type affects gameplay experience. Choosing the right server is important for enjoyment.', 'server population,pvp servers,pve servers,economy,rulesets,experience,open world combat,active economies,empty cities,gameplay,enjoyment,high population,low population', 'general,servers,population,rules');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_character_creation', 'Character Creation Tips', 'Choose race/class combinations that fit your playstyle. Some races provide better starting zones or racial abilities. Consider faction balance on your server. Think about long-term goals when creating characters. Server transfers allow changing servers later. Character names must be unique.', 'character creation,race,class,playstyle,starting zones,racial abilities,faction balance,long term goals,server transfer,unique names,combinations', 'general,character,creation,planning');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_time_management', 'In-Game Time Management', 'World of Warcraft has a day/night cycle that affects gameplay. Some quests or events only occur at certain times. Daily quests reset daily. Raid lockouts reset weekly. Understanding game time helps with planning. Real-world time affects in-game events and resets.', 'time management,day night cycle,daily quests,raid lockouts,resets,planning,gameplay,events,real world time,weekly,understanding', 'general,time,planning,resets');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_communication', 'Communication and Community', 'Use guild chat, general chat, and trade chat for communication. Voice chat enhances coordination. Good communication is essential for group content. Community websites provide additional information. Building relationships leads to better gameplay experiences. Respect other players and follow chat etiquette.', 'communication,guild chat,voice chat,coordination,community,etiquette,general chat,trade chat,group content,websites,relationships,gameplay,respect', 'general,communication,community,social');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_gear_optimization', 'Gear Optimization', 'Stat priority depends on class and spec. Use gear comparison tools. Enchantments and gems improve gear significantly. Don''t neglect off-hand items. Reforging allows stat conversion. Understanding your class guides optimal gearing decisions. Regular gear upgrades improve performance.', 'gear optimization,stat priority,enchantments,gems,reforging,performance,class,spec,comparison tools,off hand,stat conversion,upgrades', 'general,gear,optimization,stats');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_playstyle_adaptation', 'Adapting Playstyles', 'Different content requires different approaches. Solo play, group play, PvP, raiding all have different strategies. Be flexible and learn from experiences. Try different roles and activities. Understanding various playstyles enriches the game experience. Don''t limit yourself to one type of content.', 'playstyle adaptation,solo play,group play,pvp,raiding,flexible,experiences,roles,activities,enriches,game experience,strategies', 'general,playstyle,adaptation,variety');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_burnout_prevention', 'Avoiding Burnout', 'Take breaks when feeling frustrated. Set realistic goals. Don''t feel obligated to do everything. Enjoy the journey, not just endgame. Play at your own pace. Balance gaming with real life. Burnout prevention leads to longer enjoyment of the game.', 'burnout prevention,breaks,goals,balance,pace,enjoyment,frustrated,realistic,obligated,journey,endgame,real life', 'general,health,balance,wellness');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_patch_changes', 'Understanding Patches', 'Game updates change mechanics and balance. Stay informed about upcoming changes. Some patches buff, others nerf. Class balance shifts over time. Understanding patch notes helps adapt strategies. Patches can significantly affect gameplay and require relearning.', 'patch changes,updates,balance,buffs,nerfs,adaptation,mechanics,informed,class balance,patch notes,strategies,gameplay,relearning', 'general,patches,updates,balance');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_achievement_hunting', 'Achievement Collecting', 'Achievements provide goals and rewards. Some are easy, others very challenging. Achievement hunting adds replayability. Meta achievements combine multiple goals. Titles and mounts from achievements. Achievement points provide bragging rights. Collecting achievements extends game longevity.', 'achievement hunting,goals,rewards,meta achievements,titles,mounts,replayability,challenging,bragging rights,game longevity,collecting', 'general,achievements,goals,collection');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_alt_management', 'Managing Multiple Characters', 'Alts provide different experiences and utility. Bank alts for storage, profession alts for crafting. Level alts for achievements or fun. Server transfers move characters. Managing alts requires organization. Multiple characters enhance gameplay variety and utility.', 'alt management,bank alts,profession alts,server transfers,organization,variety,utility,storage,crafting,achievements,fun,multiple characters,gameplay', 'general,alts,management,utility');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_endgame_content', 'Endgame Content Overview', 'Endgame includes raiding, PvP, achievements, professions, and reputation grinds. Different players prefer different activities. Endgame provides the most challenging content. Requires good gear and coordination. Endgame content evolves with expansions. Finding enjoyable endgame activities is key to long-term play.', 'endgame content,raiding,pvp,achievements,reputation,challenging,gear,coordination,expansions,long term play,activities,evolves', 'general,endgame,content,variety');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_learning_basics', 'Learning the Basics', 'Start with the tutorial and basic quests in your starting zone. Learn your class abilities and how to use them effectively. Understand the interface and basic controls. Practice combat against low-level enemies. Don''t be afraid to ask for help in chat. The game has a steep learning curve but becomes intuitive with practice.', 'learning basics,tutorial,starting zone,class abilities,interface,controls,combat,practice,help,chat,learning curve,intuitive', 'general,basics,learning,beginners');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_finding_groups', 'Finding Groups for Content', 'Use the automatic Dungeon Finder tool to be grouped cross-realm for a random dungeon, or fall back to the LFG channel and trade chat for group content it doesn''t cover, like raids. Be clear about what you''re looking for and good communication helps get invites. Patience is key when looking for groups. Building a reputation as a good group member helps.', 'finding groups,looking for group,lfg,communication,invites,trade chat,guild recruitment,dungeon finder,patience,reputation,good member', 'general,groups,social,content');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_addon_management', 'Managing Addons Effectively', 'Keep addons updated to avoid compatibility issues. Use a lightweight UI for better performance. Backup your WTF folder regularly. Some addons conflict with each other. Read addon descriptions carefully. Join addon communities for support. Not all addons work on all servers or with all versions.', 'addon management,updated,compatibility,lightweight ui,performance,backup,wtf folder,conflict,descriptions,communities,support,servers,versions', 'general,addons,management,technical');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_questing_efficiency', 'Questing Efficiently', 'Group similar quests together to minimize travel. Use quest helper addons for navigation. Complete daily quests for extra rewards. Some quests have follow-ups that chain together. Pay attention to quest objectives and requirements. Questing in the right level zones maximizes experience. Don''t ignore side quests for bonus rewards.', 'questing efficiency,group quests,travel,quest helper,navigation,daily quests,rewards,follow ups,objectives,requirements,level zones,experience,side quests,bonus', 'general,questing,efficiency,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_inventory_management', 'Managing Inventory and Bags', 'Use bag space efficiently by selling junk to vendors. Bank important items you don''t need immediately. Use profession bags for materials. Sort your bags regularly. Don''t carry too much weight. Some items can be disenchanted or milled for profit. Bag space is limited so prioritize what you keep.', 'inventory management,bags,bag space,vendors,bank,profession bags,materials,sort,weight,disenchanted,milled,profit,limited,prioritize', 'general,inventory,management,organization');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_reputation_grinding', 'Reputation Grinding Strategies', 'Focus on one faction at a time for faster progress. Use reputation tabards for bonus gains. Complete faction-specific quests and dailies. Kill reputation enemies in appropriate zones. Some reputations require special items or achievements. Reputation unlocks vendors, mounts, and titles. Plan your grinding to maximize rewards.', 'reputation grinding,faction,progress,tabards,bonus gains,quests,dailies,enemies,zones,special items,achievements,unlocks,vendors,mounts,titles,plan,rewards', 'general,reputation,grinding,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_raid_preparation', 'Preparing for Raids', 'Ensure you have appropriate gear and consumables. Learn boss strategies beforehand. Know your role in the raid. Practice with your class in dummy scenarios. Have backup strategies for different situations. Good preparation reduces wipes and increases success. Communication with your raid team is crucial.', 'raid preparation,gear,consumables,boss strategies,role,practice,dummy,backup strategies,situations,preparation,wipes,success,communication,raid team', 'general,raids,preparation,strategy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('general_pvp_preparation', 'PvP Preparation Tips', 'Gear up with PvP-specific items and enchants. Learn class matchups and counters. Practice in battlegrounds or world PvP. Understand crowd control and interrupts. Know when to engage and when to retreat. Team coordination is essential. PvP requires different tactics than PvE combat.', 'pvp preparation,gear,enchants,matchups,counters,practice,battlegrounds,world pvp,crowd control,interrupts,engage,retreat,coordination,tactics,pve', 'general,pvp,preparation,combat');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_utgarde_keep', 'Utgarde Keep', 'Utgarde Keep is a level 69 to 72 five-player dungeon in Howling Fjord. It is the first dungeon most players see in Northrend, a vrykul hold built into the cliffs above Daggercap Bay. Its bosses are Prince Keleseth, Dalronn the Controller, and Ingvar the Plunderer.', 'utgarde keep,uk,utgarde', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_nexus', 'The Nexus', 'The Nexus is a level 71 to 73 five-player dungeon in Coldarra, in the Borean Tundra. It is the middle ring of Malygos''s spire, and the whole place is frozen blue crystal. Its bosses are Commander Stoutbeard, Grand Magus Telestra, Anomalus, Ormorok the Tree-Shaper, and Keristrasza.', 'the nexus,nexus', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_azjol_nerub', 'Azjol-Nerub', 'Azjol-Nerub is a level 72 to 74 five-player dungeon in Dragonblight. It is a short three-boss run straight down through the old nerubian kingdom, and the second boss fight happens while you retreat up a web tunnel. Its bosses are Krik''thir the Gatewatcher, Hadronox, and Anub''arak.', 'azjol nerub,azjol-nerub,an,nerub', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ahn_kahet_the_old_kingdom', 'Ahn''kahet: The Old Kingdom', 'Ahn''kahet: The Old Kingdom is a level 73 to 75 five-player dungeon in Dragonblight. It shares an entrance area with Azjol-Nerub but runs deeper and darker, and Amanitar only appears on heroic difficulty. Its bosses are Elder Nadox, Prince Taldaram, Jedoga Shadowseeker, Amanitar, and Herald Volazj.', 'ahnkahet,the old kingdom,old kingdom,ok', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_drak_tharon_keep', 'Drak''Tharon Keep', 'Drak''Tharon Keep is a level 74 to 76 five-player dungeon in on the border between the Grizzly Hills and Zul''Drak. It is a Drakkari troll fortress, and King Dred at the end is a devilsaur kept as a pet. Its bosses are Trollgore, Novos the Summoner, and King Dred.', 'draktharon keep,draktharon,dtk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_violet_hold', 'Violet Hold', 'Violet Hold is a level 75 to 77 five-player dungeon in Dalaran. It is a prison break rather than a crawl: you hold a room against timed waves while sealed cells open, and which mini-bosses you get is randomised each run. Its bosses are Erekem, Moragg, Ichoron, Xevozz, Lavanthor, Zuramat the Obliterator, and Cyanigosa.', 'violet hold,vh', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_gundrak', 'Gundrak', 'Gundrak is a level 76 to 78 five-player dungeon in Zul''Drak. It is where the Drakkari are butchering their own animal gods, and Eck the Ferocious is a bonus boss that only exists on heroic. Its bosses are Slad''ran, Moorabi, Drakkari Colossus, Gal''darah, and Eck the Ferocious.', 'gundrak,gd', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_halls_of_stone', 'Halls of Stone', 'Halls of Stone is a level 77 to 79 five-player dungeon in The Storm Peaks. The middle of it is the Tribunal of Ages, an escort-and-defend event where Brann Bronzebeard reads titan records while you keep him alive. Its bosses are Krystallus, Maiden of Grief, and Sjonnir The Ironshaper.', 'halls of stone,hos', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_halls_of_lightning', 'Halls of Lightning', 'Halls of Lightning is a level 79 to 80 five-player dungeon in The Storm Peaks. It sits above Halls of Stone in the same titan complex, and Loken at the end is a straight damage race against a stacking pulse. Its bosses are General Bjarngrim, Volkhan, Ionar, and Loken.', 'halls of lightning,hol', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_utgarde_pinnacle', 'Utgarde Pinnacle', 'Utgarde Pinnacle is a level 79 to 80 five-player dungeon in Howling Fjord. It is the upper half of the same vrykul keep as Utgarde Keep but tuned for level 80, and Skadi is fought from the back of a drake. Its bosses are Svala Sorrowgrave, Gortok Palehoof, Skadi the Ruthless, and King Ymiron.', 'utgarde pinnacle,up,pinnacle', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_oculus', 'The Oculus', 'The Oculus is a level 79 to 80 five-player dungeon in Coldarra, in the Borean Tundra. Most of it is fought from drake mounts in mid-air, which made it the least popular dungeon in the Dungeon Finder by a wide margin. Its bosses are Drakos the Interrogator, Varos Cloudstrider, Mage-Lord Urom, and Ley-Guardian Eregos.', 'the oculus,oculus,occ', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_culling_of_stratholme', 'The Culling of Stratholme', 'The Culling of Stratholme is a level 79 to 80 five-player dungeon in the Caverns of Time in Tanaris. It replays Arthas purging Stratholme, and beating the optional timed run rewards the Bronze Drake mount. Its bosses are Meathook, Salramm the Fleshcrafter, Chrono-Lord Epoch, and Mal''Ganis.', 'culling of stratholme,cos,strat cot', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_trial_of_the_champion', 'Trial of the Champion', 'Trial of the Champion is a level 79 to 80 five-player dungeon in the Argent Tournament grounds in Icecrown. It opens with a mounted jousting round using vehicle controls before turning into a normal fight. Its bosses are The Grand Champions, Eadric the Pure, Argent Confessor Paletress, and The Black Knight.', 'trial of the champion,toc5,totc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_forge_of_souls', 'The Forge of Souls', 'The Forge of Souls is a level 79 to 80 five-player dungeon in Icecrown Citadel. It is the first of the three patch 3.3 dungeons that lead into Icecrown Citadel itself. Its bosses are Bronjahm, and Devourer of Souls.', 'forge of souls,fos', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_pit_of_saron', 'Pit of Saron', 'Pit of Saron is a level 79 to 80 five-player dungeon in Icecrown Citadel. The last stretch is a scripted escape with Jaina or Sylvanas clearing the way ahead of you. Its bosses are Forgemaster Garfrost, Ick, Krick, and Scourgelord Tyrannus.', 'pit of saron,pos', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_halls_of_reflection', 'Halls of Reflection', 'Halls of Reflection is a level 79 to 80 five-player dungeon in Icecrown Citadel. It is two bosses and then a fighting retreat from the Lich King himself, who cannot be killed here. Its bosses are Falric, Marwyn, and The Lich King.', 'halls of reflection,hor', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_naxxramas', 'Naxxramas', 'Naxxramas is a level 80 ten- and twenty-five-player raid in Dragonblight. It was moved from the Eastern Plaguelands and retuned for level 80 as Wrath''s entry raid; it is split into the Arachnid, Plague, Military and Construct quarters, which can be cleared in any order before Sapphiron and Kel''Thuzad. Its bosses are Anub''Rekhan, Grand Widow Faerlina, Maexxna, Noth the Plaguebringer, Heigan the Unclean, Loatheb, Instructor Razuvious, Gothik the Harvester, The Four Horsemen, Patchwerk, Grobbulus, Gluth, Thaddius, Sapphiron, and Kel''Thuzad.', 'naxxramas,naxx,scourge,necropolis', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_obsidian_sanctum', 'The Obsidian Sanctum', 'The Obsidian Sanctum is a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. Leaving Sartharion''s three drake lieutenants alive raises the difficulty and the loot, which is where the ''Sartharion plus three drakes'' achievement runs come from. Its bosses are Tenebron, Shadron, Vesperon, and Sartharion.', 'obsidian sanctum,os,sarth', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_eye_of_eternity', 'The Eye of Eternity', 'The Eye of Eternity is a level 80 ten- and twenty-five-player raid in Coldarra, in the Borean Tundra. It is a single fight against Malygos that ends with the whole raid on drakes in a vehicle phase. Its boss is Malygos.', 'eye of eternity,eoe,malygos raid', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ulduar', 'Ulduar', 'Ulduar is a level 80 ten- and twenty-five-player raid in The Storm Peaks. It opens with a vehicle assault on Flame Leviathan, and most bosses have an optional harder ''hard mode'' triggered in-fight rather than by a difficulty setting; Algalon is a limited-attempt bonus encounter. Its bosses are Flame Leviathan, Ignis the Furnace Master, Razorscale, XT-002 Deconstructor, The Assembly of Iron, Kologarn, Auriaya, Hodir, Thorim, Freya, Mimiron, General Vezax, Yogg-Saron, and Algalon the Observer.', 'ulduar,titan,siege of ulduar,inner sanctum', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_trial_of_the_crusader', 'Trial of the Crusader', 'Trial of the Crusader is a level 80 ten- and twenty-five-player raid in the Argent Tournament grounds in Icecrown. It is a single arena room with no trash at all, run as five staged encounters; the Heroic version is separately locked and limited by a shared attempt counter. Its bosses are Northrend Beasts, Lord Jaraxxus, Faction Champions, Twin Val''kyr, and Anub''arak.', 'trial of the crusader,toc,totc25', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_icecrown_citadel', 'Icecrown Citadel', 'Icecrown Citadel is a level 80 ten- and twenty-five-player raid in Icecrown. It is the final raid of Wrath of the Lich King, released wing by wing over patch 3.3, and ends with the Lich King on the roof of the Frozen Throne. Its bosses are Lord Marrowgar, Lady Deathwhisper, Gunship Battle, Deathbringer Saurfang, Festergut, Rotface, Professor Putricide, Prince Valanar, Blood-Queen Lana''thel, Valithria Dreamwalker, Sindragosa, and The Lich King.', 'icecrown citadel,icc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_vault_of_archavon', 'Vault of Archavon', 'Vault of Archavon is a level 80 ten- and twenty-five-player raid in Wintergrasp. Access is a PvP prize rather than a raid lockout: only the faction currently holding Wintergrasp can enter, and each boss drops a mix of PvP and PvE gear. Its bosses are Archavon the Stone Watcher, Emalon the Storm Watcher, Koralon the Flame Watcher, and Toravon the Ice Watcher.', 'vault of archavon,voa,archavon', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_ruby_sanctum', 'The Ruby Sanctum', 'The Ruby Sanctum is a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. It arrived in patch 3.3.5 as the last raid of the expansion, and Halion is fought in both a physical and a shadow version of the room at once. Its bosses are Baltharus the Warborn, General Zarithrian, Saviana Ragefire, and Halion.', 'ruby sanctum,rs,halion', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_onyxia_s_lair', 'Onyxia''s Lair', 'Onyxia''s Lair is a level 80 ten- and twenty-five-player raid in Dustwallow Marsh. Originally a level 60 raid, it was retuned to level 80 in patch 3.2.2 for the game''s fifth anniversary and drops current Wrath-tier loot. Its boss is Onyxia.', 'onyxias lair,onyxia,ony,black dragon,dragonmurk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_hellfire_citadel_ramparts', 'Hellfire Citadel: Ramparts', 'Hellfire Citadel: Ramparts is a level 59 to 62 five-player dungeon in Hellfire Peninsula. It is the first Outland dungeon most players run, and much of it is fought on open walkways rather than corridors. Its bosses are Watchkeeper Gargolmar, Omor the Unscarred, and Vazruden the Herald.', 'hellfire ramparts,ramparts,hfr', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_hellfire_citadel_the_blood_furnace', 'Hellfire Citadel: The Blood Furnace', 'Hellfire Citadel: The Blood Furnace is a level 61 to 63 five-player dungeon in Hellfire Peninsula. It is where the Legion was mass-producing fel orcs, and the middle boss is fought through a sequence of gas-filled cells. Its bosses are The Maker, Broggok, and Keli''dan the Breaker.', 'blood furnace,bf', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_coilfang_the_slave_pens', 'Coilfang: The Slave Pens', 'Coilfang: The Slave Pens is a level 62 to 64 five-player dungeon in Zangarmarsh. It is the shallowest of the three Coilfang wings and the usual first stop for a Cenarion Expedition reputation grind. Its bosses are Mennu the Betrayer, Rokmar the Crackler, and Quagmirran.', 'slave pens,sp', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_coilfang_the_underbog', 'Coilfang: The Underbog', 'Coilfang: The Underbog is a level 63 to 65 five-player dungeon in Zangarmarsh. The Black Stalker at the bottom is a giant electrified spider that levitates the party. Its bosses are Hungarfen, Ghaz''an, Swamplord Musel''ek, and The Black Stalker.', 'underbog,ub', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_auchindoun_mana_tombs', 'Auchindoun: Mana-Tombs', 'Auchindoun: Mana-Tombs is a level 64 to 66 five-player dungeon in Terokkar Forest. It is the Consortium''s wing of Auchindoun, and the ethereal prince at the end is one of the easier Outland end bosses. Its bosses are Pandemonius, Tavarok, and Nexus-Prince Shaffar.', 'mana tombs,mt', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_auchindoun_auchenai_crypts', 'Auchindoun: Auchenai Crypts', 'Auchindoun: Auchenai Crypts is a level 65 to 67 five-player dungeon in Terokkar Forest. It is full of undead draenei, and Shirrak the Dead Watcher slows casting for the whole room. Its bosses are Shirrak the Dead Watcher, and Exarch Maladaar.', 'auchenai crypts,crypts,ac', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_opening_of_the_dark_portal', 'Opening of the Dark Portal', 'Opening of the Dark Portal is a level 66 to 68 five-player dungeon in the Caverns of Time in Tanaris. Players usually call it the Black Morass. It is a timed defence of Medivh through eighteen portal waves at the moment the Dark Portal was first opened, and it was the attunement step for Karazhan. The Dark Portal itself stands in the Blasted Lands, and this instance is only a vision of its past. Its bosses are Chrono Lord Deja, Temporus, and Aeonus.', 'black morass,bm,opening of the dark portal,cot2', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_auchindoun_sethekk_halls', 'Auchindoun: Sethekk Halls', 'Auchindoun: Sethekk Halls is a level 67 to 68 five-player dungeon in Terokkar Forest. The arakkoa wing of Auchindoun, and on heroic it holds Anzu, the raven god summoned by druids for their flight-form quest. Its bosses are Darkweaver Syth, Talon King Ikiss, and Anzu.', 'sethekk halls,sethekk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_auchindoun_shadow_labyrinth', 'Auchindoun: Shadow Labyrinth', 'Auchindoun: Shadow Labyrinth is a level 69 to 70 five-player dungeon in Terokkar Forest. It is the longest and hardest Auchindoun wing, and Murmur at the end is a sound elemental with a room-wide pull-and-detonate. Its bosses are Ambassador Hellmaw, Blackheart the Inciter, Grandmaster Vorpil, and Murmur.', 'shadow labyrinth,shadow lab,slabs', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_hellfire_citadel_the_shattered_halls', 'Hellfire Citadel: The Shattered Halls', 'Hellfire Citadel: The Shattered Halls is a level 69 to 70 five-player dungeon in Hellfire Peninsula. It has a reputation as the hardest of the Hellfire wings, and its heroic version runs on a timer to rescue prisoners. Its bosses are Grand Warlock Nethekurse, Blood Guard Porung, Warbringer O''mrogg, and Warchief Kargath Bladefist.', 'shattered halls,sh', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_coilfang_the_steamvault', 'Coilfang: The Steamvault', 'Coilfang: The Steamvault is a level 69 to 70 five-player dungeon in Zangarmarsh. It is the deepest Coilfang wing and the last step of the old Karazhan-era Cenarion Expedition grind. Its bosses are Hydromancer Thespia, Mekgineer Steamrigger, and Warlord Kalithresh.', 'steamvault,sv', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_tempest_keep_the_mechanar', 'Tempest Keep: The Mechanar', 'Tempest Keep: The Mechanar is a level 69 to 70 five-player dungeon in Netherstorm. It is one of the three satellite wings of Tempest Keep, all mechanical, and the shortest of them. Its bosses are Mechano-Lord Capacitus, Nethermancer Sepethrea, and Pathaleon the Calculator.', 'mechanar,mech', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_tempest_keep_the_botanica', 'Tempest Keep: The Botanica', 'Tempest Keep: The Botanica is a level 69 to 70 five-player dungeon in Netherstorm. It is a greenhouse wing of Tempest Keep, and Warp Splinter at the end summons saplings that must be killed fast. Its bosses are Commander Sarannis, High Botanist Freywinn, Thorngrin the Tender, Laj, and Warp Splinter.', 'botanica,bot', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_tempest_keep_the_arcatraz', 'Tempest Keep: The Arcatraz', 'Tempest Keep: The Arcatraz is a level 69 to 70 five-player dungeon in Netherstorm. It is a prison wing holding things the naaru locked away, and it was the attunement step for the Black Temple. Its bosses are Zereketh the Unbound, Dalliah the Doomsayer, Wrath-Scryer Soccothrates, and Harbinger Skyriss.', 'arcatraz,arc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_magister_s_terrace', 'Magister''s Terrace', 'Magister''s Terrace is a level 69 to 70 five-player dungeon in the Isle of Quel''Danas. It was added in patch 2.4 as the last Burning Crusade dungeon, and its heroic mode drops the Swift White Hawkstrider mount. Its bosses are Selin Fireheart, Vexallus, Priestess Delrissa, and Kael''thas Sunstrider.', 'magisters terrace,mgt,magister''s terrace', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_karazhan', 'Karazhan', 'Karazhan is a level 70 to 73 ten-player raid in Deadwind Pass. It is Medivh''s abandoned tower and the entry raid of the Burning Crusade, known for its chess event and an optional opera encounter that rotates between three scripts. Its bosses are Attumen the Huntsman, Moroes, Maiden of Virtue, Opera Event, The Curator, Terestian Illhoof, Shade of Aran, Netherspite, Chess Event, Prince Malchezaar, and Nightbane.', 'karazhan,kara,kz', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_gruul_s_lair', 'Gruul''s Lair', 'Gruul''s Lair is a level 70 twenty-five-player raid in Blade''s Edge Mountains. Two bosses only: a five-ogre council fight and then Gruul himself, who grows in size and damage on a timer. Its bosses are High King Maulgar, and Gruul the Dragonkiller.', 'gruuls lair,gruul', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_magtheridon_s_lair', 'Magtheridon''s Lair', 'Magtheridon''s Lair is a level 70 twenty-five-player raid in Hellfire Peninsula. A single boss beneath Hellfire Citadel, fought while five channelers hold him in place. Its boss is Magtheridon.', 'magtheridons lair,magtheridon,mag', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_coilfang_serpentshrine_cavern', 'Coilfang: Serpentshrine Cavern', 'Coilfang: Serpentshrine Cavern is a level 70 twenty-five-player raid in Zangarmarsh. It is the raid wing of Coilfang Reservoir and ends with Lady Vashj, whose fight requires relaying tainted cores between phases. Its bosses are Hydross the Unstable, The Lurker Below, Leotheras the Blind, Fathom-Lord Karathress, Morogrim Tidewalker, and Lady Vashj.', 'serpentshrine cavern,ssc,vashj', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_tempest_keep', 'Tempest Keep', 'Tempest Keep is a level 70 twenty-five-player raid in Netherstorm. Usually called The Eye; it is the central spire of Tempest Keep and ends with Kael''thas Sunstrider in a long multi-phase fight. Its bosses are Al''ar, Void Reaver, High Astromancer Solarian, and Kael''thas Sunstrider.', 'tempest keep,the eye,tk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_battle_for_mount_hyjal', 'The Battle for Mount Hyjal', 'The Battle for Mount Hyjal is a level 70 twenty-five-player raid in the Caverns of Time in Tanaris. It replays the battle at the World Tree as eight waves of trash between bosses, which makes it far more trash-heavy than any other raid of its tier. Its bosses are Rage Winterchill, Anetheron, Kaz''rogal, Azgalor, and Archimonde.', 'mount hyjal,hyjal,mh,battle for mount hyjal', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_black_temple', 'Black Temple', 'Black Temple is a level 70 twenty-five-player raid in Shadowmoon Valley. Illidan Stormrage''s fortress and the intended final raid of the Burning Crusade before the Sunwell was added. Its bosses are High Warlord Naj''entus, Supremus, Shade of Akama, Teron Gorefiend, Gurtogg Bloodboil, Reliquary of Souls, Mother Shahraz, The Illidari Council, and Illidan Stormrage.', 'black temple,bt,illidan', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_zul_aman', 'Zul''Aman', 'Zul''Aman is a level 70 to 73 ten-player raid in the Ghostlands. Added in patch 2.3, it runs on a timer: clearing the four animal-god bosses fast enough rewards the Amani War Bear. Its bosses are Akil''zon, Nalorakk, Jan''alai, Halazzi, Hex Lord Malacrass, and Zul''jin.', 'zulaman,za', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_the_sunwell', 'The Sunwell', 'The Sunwell is a level 70 twenty-five-player raid in the Isle of Quel''Danas. Added in patch 2.4 as the final raid of the Burning Crusade, and its gear was the last tier before Wrath launched. Its bosses are Kalecgos, Brutallus, Felmyst, The Eredar Twins, M''uru, and Kil''jaeden.', 'sunwell plateau,sunwell,swp', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ragefire_chasm', 'Ragefire Chasm', 'Ragefire Chasm is a level 15 to 16 five-player dungeon in Orgrimmar, through the Cleft of Shadow. It is the lowest-level dungeon in the game and the only one inside a capital city. Its bosses are Oggleflint, Taragaman the Hungerer, Jergosh the Invoker, and Bazzalan.', 'ragefire chasm,rfc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_deadmines', 'Deadmines', 'Deadmines is a level 17 to 20 five-player dungeon in Westfall. It runs through a mine and out onto a pirate ship moored in a cavern, and Edwin VanCleef leads the Defias Brotherhood at the end. Its bosses are Rhahk''Zor, Sneed, Gilnid, Mr. Smite, Cookie, Captain Greenskin, and Edwin VanCleef.', 'deadmines,vc,the deadmines,mine cart,van cleef,defias', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_wailing_caverns', 'Wailing Caverns', 'Wailing Caverns is a level 17 to 20 five-player dungeon in the Barrens. It is a maze of twisting tunnels with no clear route, which is most of its reputation. Its bosses are Lady Anacondra, Lord Cobrahn, Kresh, Lord Pythas, Skum, Lord Serpentis, Verdan the Everliving, and Mutanus the Devourer.', 'wailing caverns,wc,naralex,emerald dream', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_shadowfang_keep', 'Shadowfang Keep', 'Shadowfang Keep is a level 18 to 21 five-player dungeon in Silverpine Forest. It is a haunted worgen castle, and the renegade mage Archmage Arugal waits at the top. Its bosses are Rethilgore, Razorclaw the Butcher, Baron Silverlaine, Commander Springvale, Odo the Blindwatcher, Fenrus the Devourer, Wolf Master Nandos, and Archmage Arugal.', 'shadowfang keep,sfk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_blackfathom_deeps', 'Blackfathom Deeps', 'Blackfathom Deeps is a level 21 to 24 five-player dungeon in Ashenvale. A flooded night elf temple to an old naga-worshipped god, with a long underwater stretch. Its bosses are Ghamoo-ra, Lady Sarevess, Gelihast, Lorgus Jett, Old Serra''kis, Twilight Lord Kelris, and Aku''mai.', 'blackfathom deeps,bfd,twilight hammer', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_stormwind_stockade', 'Stormwind Stockade', 'Stormwind Stockade is a level 22 to 25 five-player dungeon in Stormwind City. A short prison-riot dungeon under the Trade District, and one of the fastest runs in the game. Its bosses are Targorr the Dread, Kam Deepfury, Hamhock, Bazil Thredd, and Dextren Ward.', 'stockade,stocks,stormwind stockade', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_razorfen_kraul', 'Razorfen Kraul', 'Razorfen Kraul is a level 24 to 27 five-player dungeon in the Southern Barrens. An outdoor quilboar warren built from thorns rather than an indoor dungeon. Its bosses are Roogug, Aggem Thorncurse, Death Speaker Jargba, Overlord Ramtusk, Agathelos the Raging, and Charlga Razorflank.', 'razorfen kraul,rfk', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_gnomeregan', 'Gnomeregan', 'Gnomeregan is a level 25 to 28 five-player dungeon in Dun Morogh. The irradiated gnome capital, and Mekgineer Thermaplugg at the end is fought around a room of bomb-dispensing panels. Its bosses are Grubbis, Viscous Fallout, Electrocutioner 6000, Crowd Pummeler 9-60, and Mekgineer Thermaplugg.', 'gnomeregan,gnomer', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_scarlet_monastery', 'Scarlet Monastery', 'Scarlet Monastery is a level 29 to 40 five-player dungeon in Tirisfal Glades. It is four separate wings behind one entrance -- Graveyard, Library, Armory and Cathedral -- run at increasing levels rather than as one dungeon. Its bosses are Interrogator Vishas, Bloodmage Thalnos, Houndmaster Loksey, Arcanist Doan, Herod, High Inquisitor Fairbanks, and High Inquisitor Whitemane.', 'scarlet monastery,sm,smc', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_razorfen_downs', 'Razorfen Downs', 'Razorfen Downs is a level 34 to 37 five-player dungeon in the Southern Barrens. The undead half of the quilboar warrens, ending with the lich Amnennar the Coldbringer. Its bosses are Tuten''kash, Mordresh Fire Eye, Glutton, and Amnennar the Coldbringer.', 'razorfen downs,rfd', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_uldaman', 'Uldaman', 'Uldaman is a level 37 to 40 five-player dungeon in the Badlands. A titan vault, and the first place most players meet the dwarves'' own origin story. Its bosses are Revelosh, Baelog, Ironaya, Ancient Stone Keeper, Galgann Firehammer, Grimlok, and Archaedas.', 'uldaman,ulda', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_maraudon', 'Maraudon', 'Maraudon is a level 41 to 48 five-player dungeon in Desolace. Split into orange, purple and pristine sections with separate entrances, ending at Princess Theradras. Its bosses are Noxxion, Razorlash, Lord Vyletongue, Celebras the Cursed, Landslide, Tinkerer Gizlock, Rotgrip, and Princess Theradras.', 'maraudon,mara,centaur,valley of spears', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_zul_farrak', 'Zul''Farrak', 'Zul''Farrak is a level 43 to 46 five-player dungeon in Tanaris. Best known for the pyramid steps, where a huge troll wave attacks at once, and for Gahz''rilla. Its bosses are Hydromancer Velratha, Antu''sul, Theka the Martyr, Witch Doctor Zum''rah, Nekrum Gutchewer, Chief Ukorz Sandscalp, and Gahz''rilla.', 'zulfarrak,zf,sandfury,antusul', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_sunken_temple', 'Sunken Temple', 'Sunken Temple is a level 47 to 50 five-player dungeon in the Swamp of Sorrows. Properly the Temple of Atal''Hakkar; it is a confusing layered ruin and a long run for its level. Its bosses are Atal''alarion, Dreamscythe, Weaver, Jammal''an the Prophet, Morphaz, Hazzas, and Shade of Eranikus.', 'sunken temple,st,temple of atalhakkar,atal''ai,avatar of hakkar', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_blackrock_depths', 'Blackrock Depths', 'Blackrock Depths is a level 49 to 56 five-player dungeon in Blackrock Mountain. By far the largest dungeon in the game, with a bar, an arena and a prison inside it, ending at Emperor Dagran Thaurissan. Its bosses are Lord Roccor, High Interrogator Gerstahn, Houndmaster Grebmar, Pyromancer Loregrain, Lord Incendius, Warder Stilgiss, Fineous Darkvire, Bael''Gar, General Angerforge, Golem Lord Argelmach, Ambassador Flamelash, Magmus, and Emperor Dagran Thaurissan.', 'blackrock depths,brd,dark iron,dwarves', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_blackrock_spire', 'Blackrock Spire', 'Blackrock Spire is a level 57 to 63 five- and ten-player dungeon in Blackrock Mountain. Split into Lower and Upper halves sharing one entrance; Upper was originally a ten-player raid. Its bosses are Highlord Omokk, Shadow Hunter Vosh''gajin, War Master Voone, Mother Smolderweb, Quartermaster Zigris, Halycon, Overlord Wyrmthalak, Pyroguard Emberseer, Warchief Rend Blackhand, The Beast, and General Drakkisath.', 'blackrock spire,lbrs,ubrs,burning steppes,dragonkin', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_dire_maul', 'Dire Maul', 'Dire Maul is a level 55 to 60 five-player dungeon in Feralas. Three separate wings -- East, West and North -- and the North wing has a well-known trick for looting the king''s tribute without killing him. Its bosses are Zevrim Thornhoof, Hydrospawn, Lethtendris, Alzzin the Wildshaper, Illyanna Ravenoak, Magister Kalendris, Immol''thar, Tendris Warpwood, Prince Tortheldrin, Guard Mol''dar, Stomper Kreeg, Guard Fengus, Guard Slip''kik, Captain Kromcrush, Cho''Rush the Observer, and King Gordok.', 'dire maul,dm east,dm west,dm north,warpwood quarter,capital gardens,gordok commons,ogres,pusillin', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_scholomance', 'Scholomance', 'Scholomance is a level 58 to 60 five-player dungeon in the Western Plaguelands. A necromancy school inside Caer Darrow, ending with Darkmaster Gandling. Its bosses are Jandice Barov, Rattlegore, Marduk Blackpool, Vectus, Ras Frostwhisper, Instructor Malicia, Doctor Theolen Krastinov, Lorekeeper Polkelt, The Ravenian, Lord Alexei Barov, Lady Illucia Barov, and Darkmaster Gandling.', 'scholomance,scholo,kirtonos,scourge,caer darrow', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_stratholme', 'Stratholme', 'Stratholme is a level 58 to 60 five-player dungeon in the Eastern Plaguelands. Two separate entrances: the Scarlet side and the undead side, where Baron Rivendare drops the Deathcharger''s Reins on a timed run. Its bosses are The Unforgiven, Hearthsinger Forresten, Timmy the Cruel, Cannon Master Willey, Archivist Galford, Balnazzar, Baroness Anastari, Nerub''enkan, Maleki the Pallid, Ramstein the Gorger, Magistrate Barthilas, and Baron Rivendare.', 'stratholme,strat,live side,baron run,scarlet crusade,scourge,plague', 'instance,dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_molten_core', 'Molten Core', 'Molten Core is a level 60 to 63 forty-player raid in Blackrock Mountain. The game''s first full raid tier, ten bosses ending at Ragnaros, and the source of Tier 1 armour. Its bosses are Lucifron, Magmadar, Gehennas, Garr, Shazzrah, Baron Geddon, Sulfuron Harbinger, Golemagg the Incinerator, Majordomo Executus, and Ragnaros.', 'molten core,mc,fire elementals', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_blackwing_lair', 'Blackwing Lair', 'Blackwing Lair is a level 60 to 63 forty-player raid in Blackrock Mountain. Nefarian''s lair above Blackrock Spire, and the source of Tier 2 armour. Its bosses are Razorgore the Untamed, Vaelastrasz the Corrupt, Broodlord Lashlayer, Firemaw, Ebonroc, Flamegor, Chromaggus, and Nefarian.', 'blackwing lair,bwl,black dragonflight,drakes', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_zul_gurub', 'Zul''Gurub', 'Zul''Gurub is a level 57 to 63 twenty-player raid in Stranglethorn Vale. A troll city raid on a three-day lockout, ending at the blood god Hakkar. Its bosses are High Priest Venoxis, High Priestess Jeklik, High Priestess Mar''li, Bloodlord Mandokir, Gahz''ranka, High Priest Thekal, High Priestess Arlokk, Jin''do the Hexxer, and Hakkar.', 'zulgurub,zg,gurubashi', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ruins_of_ahn_qiraj', 'Ruins of Ahn''Qiraj', 'Ruins of Ahn''Qiraj is a level 60 to 63 twenty-player raid in Silithus. The smaller of the two Ahn''Qiraj raids, opened by the same war effort as the Temple. Its bosses are Kurinnaxx, General Rajaxx, Moam, Buru the Gorger, Ayamiss the Hunter, and Ossirian the Unscarred.', 'ruins of ahnqiraj,aq20,qiraji,silithid', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('instance_ahn_qiraj_temple', 'Ahn''Qiraj Temple', 'Ahn''Qiraj Temple is a level 60 to 63 forty-player raid in Silithus. The larger Ahn''Qiraj raid, ending at C''Thun, and the source of Tier 2.5 armour. Its bosses are The Prophet Skeram, Battleguard Sartura, Fankriss the Unyielding, Viscidus, Princess Huhuran, Twin Emperors, Ouro, and C''Thun.', 'temple of ahnqiraj,aq40,aq,qiraji,silithid', 'instance,raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_tier_sets', 'Tier Sets', 'Tier sets are high-level armor sets obtained from raid bosses. Each tier provides significant stat bonuses when multiple pieces are equipped. Tier 1 (Molten Core), Tier 2 (Blackwing Lair), and Tier 3 (the original 40-player Naxxramas) are the Classic-era sets; the Burning Crusade and Wrath raids continued the numbering with Tier 4 through Tier 10. Tier sets are highly sought after for their power and prestige, and many players collect complete sets for achievements and bragging rights.', 'tier sets,raid armor,set bonuses,molten core,blackwing lair,ahn qiraj,naxxramas,burning crusade,high level,stat bonuses,raid bosses,power,prestige,achievements,bragging rights,collect,complete sets', 'items,equipment,raid,tier');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_legendary_weapons', 'Legendary Weapons', 'Legendary weapons are the most powerful items in the game, requiring extensive quests and rare materials to obtain. Examples include Sulfuras, Hand of Ragnaros (assembled after defeating Ragnaros in Molten Core), Thunderfury, Blessed Blade of the Windseeker (pieced together through a Molten Core quest chain), and Atiesh, Greatstaff of the Guardian (a Naxxramas quest reward tied to the archmage Medivh''s lore). These weapons have unique appearances, powerful stats, and often special abilities. Obtaining a legendary weapon is a major accomplishment that requires dedication and coordination with other players.', 'legendary weapons,sulfuras,thunderfury,atiesh,ragnaros,thunderaan,medivh,quests,rare materials,unique appearances,powerful stats,special abilities,accomplishment,dedication,coordination', 'items,weapons,legendary,rare');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_profession_tools', 'Profession Tools', 'Profession tools enhance crafting success rates and provide bonuses to created items. Blacksmiths use hammers and anvils, leatherworkers use knives and sewing kits, alchemists use mortars and pestles. Higher quality tools provide better bonuses. Some tools are bind-on-equip and can be upgraded. Having good tools is essential for professional crafters who want to create high-quality items.', 'profession tools,crafting,blacksmithing,leatherworking,alchemy,hammers,anvils,knives,sewing kits,mortars,pestles,higher quality,bonuses,bind on equip,upgraded,essential,high quality items', 'items,professions,tools,crafting');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_mounts_collection', 'Mount Collection', 'World of Warcraft features hundreds of mounts with unique appearances and abilities. Rare mounts like the Ashes of Al''ar (Phoenix), Swift Zulian Tiger, or Deathcharger''s Reins are highly prized. Some mounts are obtained through achievements, others through rare drops or expensive purchases. Mount collecting is a popular pastime. Epic flying mounts become available at level 70 with the appropriate riding skill.', 'mounts collection,ashes of al ar,swift zulian tiger,deathchargers reins,phoenix,unique appearances,abilities,rare,prized,achievements,rare drops,expensive purchases,pastime,epic flying,level 70,riding skill', 'items,mounts,collection,rare');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_enchants', 'Weapon and Armor Enchants', 'Enchants add magical properties to weapons and armor. Enchanters can create enchant scrolls or apply enchants directly. Popular weapon enchants include Crusader (paladins), Fiery Weapon, or Soulfrost. Armor enchants provide stats like +strength, +agility, or +spell power. Enchanting requires materials and skill. Good enchants can significantly improve gear performance.', 'enchants,enchanting,weapons,armor,crusader,fiery weapon,soulfrost,magical properties,enchant scrolls,apply enchants,popular,paladins,stats,strength,agility,spell power,materials,skill,improve gear,performance', 'items,enchants,enchanting,improvement');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_gems', 'Socketed Gems', 'Many high-level items have sockets that can hold gems to provide stat bonuses. Gem colors match socket colors for bonuses: red for strength/crit, yellow for intellect/hit, blue for spirit/mp5, meta gems for special effects. Jewelcrafters create gems from minerals. Gemming properly is crucial for optimizing character stats. Different specs require different gem priorities.', 'gems,sockets,jewelcrafting,red gems,yellow gems,blue gems,meta gems,stat bonuses,socket colors,strength,crit,intellect,hit,spirit,mp5,special effects,minerals,optimizing,character stats,specs,priorities', 'items,gems,jewelcrafting,optimization');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_consumables', 'Consumable Items', 'Consumables are items that provide temporary benefits when used. Food provides stat buffs, potions restore health/mana or provide temporary boosts, elixirs give longer-lasting buffs, flasks provide raid buffs. Alchemists and cooks create many consumables. Using proper consumables before encounters is essential for raid and dungeon performance. Some consumables are very rare and expensive.', 'consumables,food,potions,elixirs,flasks,buffs,temporary,stat buffs,restore health,restore mana,temporary boosts,longer lasting,raid buffs,alchemists,cooks,encounters,raid performance,dungeon performance,rare,expensive', 'items,consumables,buffs,performance');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_trade_goods', 'Trade Goods and Materials', 'Trade goods are materials used in professions. Cloth from humanoids, ore from mining nodes, leather from beasts, herbs from gathering. These materials are bought and sold on the auction house. Prices fluctuate based on demand. Professional players make gold by farming and selling materials. Understanding market values is important for both crafting and trading professions.', 'trade goods,materials,cloth,ore,leather,herbs,auction house,humanoids,mining nodes,beasts,gathering,bought and sold,prices fluctuate,demand,professional players,make gold,farming,selling,market values,crafting,trading professions', 'items,materials,trading,economy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_keys', 'Dungeon and Raid Keys', 'Keys are special items that allow access to locked areas or higher difficulty content. Examples include The Master''s Key (Karazhan), Reservoir Key (Serpentshrine Cavern), or Medallion of Karabor (Auchindoun). Some keys are obtained through quests, others from rare drops. Keys often require attunement processes. Having the right keys is necessary for accessing certain content.', 'keys,attunement,karazhan,serpentshrine,auchindoun,access', 'items,keys,access,attunement');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_containers', 'Special Containers', 'Special containers hold unique items or provide access to rare rewards. Examples include the Cache of the Legion (a locked chest found in Tempest Keep: The Mechanar), the Bag of Fishing Treasures, or the Disgusting Oozeling (a companion pet found this way). Some containers are obtained from bosses, others from achievements or rare vendors. Opening containers provides excitement and potential valuable loot.', 'containers,cache of the legion,bag of fishing treasures,disgusting oozeling,loot,unique items,rare rewards,mechanar,tempest keep,bosses,achievements,rare vendors,excitement,valuable loot,collect,contents', 'items,containers,loot,collection');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_tabards', 'Guild and Faction Tabards', 'Tabards are cosmetic chest pieces that display guild or faction affiliation. Guild tabards show guild name and colors, faction tabards show allegiance to Horde/Alliance. Tabards are obtained through reputation grinds or purchases. Wearing tabards can affect gameplay in certain areas. Some tabards provide special abilities or are required for specific content.', 'tabards,guild,faction,horde,alliance,cosmetic,reputation', 'items,cosmetic,guild,faction');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_pvp_gear', 'PvP Equipment', 'PvP gear is specialized equipment for player vs player combat. Honor gear from battlegrounds, arena gear from rated matches. PvP sets provide resilience and PvP-specific stats. Weapons like the Grand Marshal''s or High Warlord''s sets are prestigious. PvP gear often has unique appearances. Players can mix PvP and PvE gear for hybrid builds.', 'pvp gear,honor,arena,resilience,grand marshal,high warlord,player vs player,battlegrounds,rated matches,pvp sets,pvp specific stats,prestigious,unique appearances,hybrid builds', 'items,pvp,equipment,combat');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_quest_rewards', 'Quest Reward Items', 'Many quests reward unique items that tell stories or provide character development. Examples include the Corrupted Ashbringer and the Tabard of the Scarlet Crusade. Quest rewards often have lore significance and unique appearances. Some quest items are essential for class stories. Collecting quest rewards helps players experience the game''s narrative.', 'quest rewards,ashbringer,scarlet crusade,lore,narrative,unique items,character development,stories,lore significance,unique appearances,class stories,collecting,experience,game narrative', 'items,quests,lore,story');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_cosmetic', 'Cosmetic Items', 'There is no wardrobe or appearance-change system yet -- an item''s look is simply whatever is equipped, so cosmetic collecting mostly means non-combat companion pets, which follow a player around and do nothing else. Pets are earned from vendors, quest rewards, holiday events, and rare drops, and many players collect them purely for their own sake. Some weapon enchants add a visual glow or proc animation as a side effect of their stat bonus, which is the closest thing to a customizable weapon appearance available this expansion. Holiday events also hand out costume items, like Hallow''s End''s wand that temporarily transforms the user into a ghost, ninja, or wickerman.', 'cosmetic,companion pets,vanity pets,appearance,collection', 'items,cosmetic,appearance,collection');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('item_relics', 'Relics and Artifacts', 'Relics are special items that provide bonuses to certain classes. Librams for paladins, idols for druids, totems for shamans. Relics are equipped in off-hand slots and provide unique bonuses. Some relics are very rare and powerful. Relics often have lore connections to class stories. Obtaining powerful relics is a goal for many players.', 'relics,artifacts,librams,idols,totems,offhand,bonuses,paladins,druids,shamans,equipped,unique bonuses,rare,powerful,lore connections,class stories,obtaining,goal', 'items,relics,class,bonuses');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_reputation', 'Reputation System', 'The reputation system in World of Warcraft tracks your standing with various factions throughout Azeroth. Reputation is gained through quests, killing enemies, and completing faction-specific tasks. Reputation levels range from Hated to Exalted, with each level unlocking better rewards. Many factions offer unique mounts, tabards, titles, and access to exclusive vendors. Managing reputation is important for endgame progression and accessing rare items.', 'reputation,faction,standing,hated,exalted,rewards,mounts,titles,quests,killing enemies,faction specific tasks,levels,unlocking,unique,tabards,exclusive vendors,managing,endgame progression,rare items', 'mechanic,reputation,factions,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_auction_house', 'Auction House', 'The Auction House is a player-driven marketplace where players can buy and sell items, materials, and equipment. Located in major cities, it allows players to post auctions with custom prices and durations. Players can search for specific items, place bids, or buyout items immediately. The Auction House is essential for obtaining rare materials, selling crafted goods, and managing the in-game economy. Understanding market prices and timing auctions properly is key to successful trading.', 'auction,house,marketplace,buy,sell,bid,buyout,economy', 'mechanic,economy,trading,market');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_quests', 'Quest System', 'Quests are the primary way players progress through World of Warcraft. Quests are obtained from NPCs and involve various objectives like killing enemies, gathering items, or exploring areas. Completing quests rewards experience, gold, items, and reputation. Quests are color-coded by difficulty: gray (too low level), green (easy), yellow (appropriate level), orange (challenging), and red (too high level). Quest chains tell stories and guide players through zones and storylines.', 'quests,objectives,experience,gold,rewards,quest chains,storylines,npcs,killing enemies,gathering items,exploring areas,completing,color coded,difficulty,gray,green,yellow,orange,red,tell stories,guide players,zones', 'mechanic,progression,story,objectives');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_talents', 'Talent System', 'The talent system allows players to specialize their characters by spending talent points in three trees: one for each specialization. Talent points are earned every level starting from level 10. Each talent provides unique abilities, stat bonuses, or ability improvements. Players can respec (reset) their talents at class trainers for gold. Choosing the right talents is crucial for optimizing character performance in different content types like PvP, raiding, or solo play.', 'talents,specialization,talent points,trees,respec,optimization,characters,spending,earned every level,level 10,unique abilities,stat bonuses,ability improvements,reset,class trainers,gold,character performance,content types,pvp,raiding,solo play', 'mechanic,character,specialization,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_glyphs', 'Glyph System', 'Glyphs are magical inscriptions that modify spell and ability effects. Players can learn glyph recipes from inscription or purchase them from vendors. Glyphs are applied to spellbooks and provide various effects like changing spell visuals, adding procs, or modifying cooldowns. There are major glyphs (learned from recipes) and minor glyphs (purchased). Glyphs allow players to customize their abilities and optimize for specific playstyles or content.', 'glyphs,inscription,spells,abilities,modification,customization', 'mechanic,customization,spells,inscription');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_achievements', 'Achievement System', 'Achievements are goals and accomplishments that players can complete for rewards. They range from simple tasks like reaching level 80 to complex feats like defeating raid bosses on heroic difficulty. Achievements are organized into categories and provide points, titles, mounts, and other rewards. Many achievements are part of larger meta-achievements. The achievement system encourages exploration, mastery, and trying different aspects of the game.', 'achievements,goals,accomplishments,rewards,titles,mounts,exploration', 'mechanic,goals,rewards,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_pvp', 'Player vs Player Combat', 'Player vs Player (PvP) combat allows players to fight against other players. PvP can occur in the open world, battlegrounds, or arenas. Players gain honor points and ranking through victories. Honor is used to purchase PvP gear and weapons. Battlegrounds like Warsong Gulch and Arathi Basin offer structured PvP experiences. PvP requires different strategies than PvE, focusing on crowd control, burst damage, and survivability.', 'pvp,player vs player,battlegrounds,honor,ranking,arenas,combat,fight against other players,open world,honor points,victories,purchase pvp gear,weapons,warsong gulch,arathi basin,structured,strategies,pve,crowd control,burst damage,survivability', 'mechanic,combat,pvp,battlegrounds');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_mounts', 'Mount System', 'Mounts allow players to travel faster across Azeroth. Players learn riding skills from riding trainers and purchase mounts from vendors or earn them through achievements. Mounts come in various types: ground mounts, flying mounts, and aquatic mounts. Epic mounts are rare and prestigious. Mount speed increases with riding skill level. Some mounts have special abilities or appearances. Collecting mounts is a popular pastime for many players.', 'mounts,riding,travel,ground,flying,aquatic,epic', 'mechanic,travel,collection,mounts');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_pets', 'Pet System', 'Pets are companions that follow players. Hunters tame wild beasts as permanent combat pets, while other classes summon class-specific pets (Warlock demons, the Mage Water Elemental, the Death Knight ghoul). Non-combat vanity pets are obtained separately through quests, vendors, and rare drops, and are purely cosmetic followers -- there is no battle system for them; that arrives only in Mists of Pandaria. Pets add personality and utility to characters.', 'pets,companions,hunters,tame,vanity pets,cosmetic,follow players,wild beasts,warlock demons,water elemental,ghoul,personality,utility', 'mechanic,companions,pets,collection');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_guilds', 'Guild System', 'Guilds are player organizations that provide social structure and benefits. Guild members can chat, share quests, and access guild banks. Guilds can own guild houses and have guild achievements. Guild leaders can promote members to different ranks with varying permissions. Guilds participate in guild vs guild activities and can earn guild reputations. Being in a guild provides a sense of community and shared goals.', 'guilds,organizations,guild bank,ranks,community,guild vs guild,player organizations,social structure,benefits,guild members,chat,share quests,access,guild houses,guild achievements,guild leaders,promote members,permissions,activities,guild reputations,sense of community,shared goals', 'mechanic,social,guilds,community');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_instances', 'Instance System', 'Instances are separate areas of the game world that provide focused gameplay experiences. Dungeons are 5-player instances with quests and bosses. Raids are larger instances for coordinated groups. Instances have different difficulty levels and lockout timers. Players can reset instances or extend lockouts with special items. Instances provide better loot and challenges than open world content. They require coordination and strategy to complete successfully.', 'instances,dungeons,raids,lockout,difficulty,coordination', 'mechanic,instances,group_content,difficulty');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_world_events', 'World Events', 'World Events are large-scale events that affect the entire game world. Examples include the Scourge Invasion, the Ahn''Qiraj War Effort, and seasonal events like Hallow''s End or Brewfest. World Events involve special quests, bosses, and rewards. They bring players together for massive coordinated efforts. Participating in world events provides unique items, achievements, and experiences. These events create memorable moments in the game''s history.', 'world events,scourge invasion,ahnqiraj,seasonal,hallows end,brewfest,large scale events,affect entire game world,ahn qiraj war effort,special quests,bosses,rewards,bring players together,massive coordinated efforts,participating,unique items,achievements,experiences,memorable moments,game history', 'mechanic,events,world,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_profession_specializations', 'Profession Specializations', 'Many professions have specializations that provide unique recipes and abilities. Blacksmithing has Armorsmithing and Weaponsmithing. Leatherworking has Dragonscale, Elemental, and Tribal. Tailoring has Mooncloth, Shadoweave, and Spellfire. Engineering has Goblin and Gnomish. Alchemy has potions, elixirs, and transmutation. Choosing a specialization focuses your profession on specific types of items and unlocks exclusive recipes.', 'profession specializations,blacksmithing,leatherworking,tailoring,engineering,alchemy,unique recipes,abilities,armorsmithing,weaponsmithing,dragonscale,elemental,tribal,mooncloth,shadoweave,spellfire,goblin,gnomish,potions,elixirs,transmutation,choosing,focuses,specific types,exclusive recipes', 'mechanic,professions,specializations,crafting');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_currency', 'Currency Systems', 'World of Warcraft has multiple currency systems beyond gold. Honor points buy PvP gear and arena points buy rated gear, while Emblems -- earned from heroic dungeons and raids -- buy PvE gear; the Emblem tier has advanced over Wrath from Heroism through Valor and Conquest to today''s Emblem of Triumph and Emblem of Frost, with older Emblems auto-converting to the current tier. Various faction tokens exist for specific reputations. Managing multiple currencies is important for gearing up characters efficiently.', 'currency,honor,arena points,emblem of triumph,emblem of frost,emblems,gold,pvp gear,rated gear,heroic gear,tokens,specific reputations,raid gear,managing,gearing up,efficiently', 'mechanic,currency,gearing,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_dungeon_finder', 'Dungeon Finder', 'The Dungeon Finder (patch 3.3, December 2009) automatically groups players across realms for a chosen dungeon or a random one, through a queue where each player selects the Tank, Healer, and/or Damage role they''ll fill. Once a group forms, everyone is teleported directly to the dungeon entrance, and abandoning the run before the group agrees to disband applies the Dungeon Deserter debuff. Queuing for a random Northrend heroic is the most common use: the first one completed each day awards 2 Emblems of Frost, and every additional one that day awards 2 Emblems of Triumph instead, making it the fastest way to gear up at level 80.', 'dungeon finder,lfg tool,random heroic,cross realm,role selection,dungeon deserter', 'mechanic,wotlk,dungeons,grouping');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_heroic_emblems', 'Heroic Dungeons and Emblems', 'Heroic difficulty unlocks at level 80 for every Northrend five-man dungeon, with no attunement or key required as there was in the Burning Crusade -- just queue for it. Heroics and raids pay Emblems rather than gold-bought tokens; by patch 3.3.5 the two currencies actually being earned are Emblem of Triumph (heroics, Trial of the Crusader, and repeat random-dungeon wins) and Emblem of Frost (Icecrown Citadel and the day''s first random heroic). The earlier Emblem of Heroism, Valor, and Conquest from Naxxramas, Ulduar, and Trial of the Crusader''s launch are no longer dropped, having been superseded as raid content advanced. Emblems are spent with quartermasters in Dalaran and Icecrown for current-tier epic gear.', 'heroic dungeons,emblem of triumph,emblem of frost,emblem of valor,emblem of conquest,emblem of heroism,quartermaster', 'mechanic,wotlk,dungeons,currency,gearing');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_dual_spec', 'Dual Talent Specialization', 'Dual talent specialization (patch 3.1) lets a character save two separate talent builds -- each with its own glyphs and action bars -- and swap between them outside combat. It costs 1000 gold, requires level 40, and is bought once from your class trainer; after that, switching between the two saved specs is free and unlimited. Players commonly keep one PvE spec and one PvP spec, or a tank/healer spec alongside a damage spec, and swap depending on what the group needs.', 'dual talent specialization,dual spec,1000 gold,level 40,class trainer', 'mechanic,wotlk,talents,character');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_cold_weather_flying', 'Cold Weather Flying', 'Cold Weather Flying is the separate skill required to use a flying mount inside Northrend; already owning Expert (280%) riding elsewhere in Azeroth doesn''t carry over automatically. Trained directly from a flying trainer in Dalaran, the Storm Peaks, or Sholazar Basin, it costs 1000 gold and still requires level 77 as of patch 3.3.5, even though Northrend''s own zones open up as early as level 68. The one shortcut is the Tome of Cold Weather Flight, a bind-to-account item a level 80 character can buy for 1000 gold and mail to their own alt, letting that alt fly in Northrend from level 68 onward instead of waiting for 77.', 'cold weather flying,flying mount,northrend,level 77,tome of cold weather flight,dalaran', 'mechanic,wotlk,flying,mounts');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_death_knight_runes', 'Death Knight Runes and Runic Power', 'Death Knights don''t use mana, rage, or energy; they run on six runes -- two Blood, two Frost, and two Unholy -- socketed into their weapon, plus a Runic Power bar. Spending a rune casts its associated ability and sends that rune on a short recharge, while Runic Power builds up as runes are spent and fuels the class''s finishing moves. Death Knights are Wrath of the Lich King''s hero class, and every one of them starts at level 55 rather than level 1, already partway through the leveling curve.', 'death knight,runes,runic power,blood rune,frost rune,unholy rune,hero class,level 55', 'mechanic,wotlk,class,death knight,resource');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mechanic_vehicle_combat', 'Vehicle Combat', 'Vehicles are a Wrath of the Lich King addition: mountable siege engines, cannons, and creatures that swap a player''s normal action bars for the vehicle''s own abilities for as long as they''re in the seat. They show up throughout the expansion -- Ulduar''s Flame Leviathan fight, the cannons defending Wintergrasp and Isle of Conquest, the siege engines and demolishers of Strand of the Ancients, and mine-cart or turret sections tucked into several dungeons. Leaving a vehicle returns a player to their normal spellbook immediately, and most vehicles can be destroyed out from under their rider by enemy fire.', 'vehicles,vehicle combat,siege engine,flame leviathan,demolisher', 'mechanic,wotlk,vehicles,pvp,raiding');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_world_bosses', 'World Bosses', 'World bosses are powerful creatures that spawn in the open world and can be attacked by any player. They drop valuable loot and provide challenging combat. Examples include Doom Lord Kazzak (a Burning Legion commander at the Dark Portal in the Blasted Lands) and Azuregos (a blue dragon in Azshara). World bosses require coordination and often drop epic items. They respawn on timers and are popular targets for guilds and groups.', 'world bosses,lord kazzak,azuregos,doom lord kazzak,loot,coordination,powerful creatures,spawn in open world,attacked by any player,valuable loot,challenging combat,burning legion,blue dragon,require coordination,epic items,respawn on timers,popular targets,guilds,groups', 'npcs,bosses,world,loot');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_rare_elites', 'Rare Elite Creatures', 'Rare elites are powerful monsters that spawn occasionally in the world. They drop rare items and achievements. Examples include the Bone Witch (Eastern Plaguelands), Snarler (Un''Goro Crater), or Krellack (Winterspring). Rare elites often have unique abilities and require strategy to defeat. Many players hunt rares for achievements and valuable drops.', 'rare elites,bone witch,snarler,krellack,achievements,drops,powerful monsters,spawn occasionally,rare items,eastern plaguelands,un goro crater,winterspring,unique abilities,require strategy,hunt rares,valuable drops', 'npcs,rare,elite,achievements');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_quest_givers', 'Important Quest Givers', 'Many NPCs provide crucial quests that advance storylines or provide rare rewards. Examples include Thrall (Orgrimmar), King Magni Bronzebeard (Ironforge), or Archmage Rhonin, leader of the Kirin Tor in Dalaran. Quest givers often have dialogue that provides lore and context. Some quest givers are part of larger quest chains that span multiple zones.', 'quest givers,thrall,king magni,archmage rhonin,lore,storylines,crucial quests,advance storylines,rare rewards,orgrimmar,ironforge,dalaran,dialogue,provides lore,context,larger quest chains,span multiple zones', 'npcs,quests,lore,story');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_class_trainers', 'Class and Profession Trainers', 'Class trainers teach new abilities and talents as players level up. Profession trainers teach crafting skills and recipes. Examples include Uthel''nay (mage trainer in Orgrimmar) or Fenthwick (rogue trainer in Stormwind). Trainers are essential for character progression. Some trainers require reputation or special access.', 'class trainers,profession trainers,uthelnay,fenthwick,abilities,talents,teach new abilities,level up,crafting skills,recipes,mage trainer,orgrimmar,hunter trainer,stormwind,essential,character progression,require reputation,special access', 'npcs,training,progression,skills');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_vendors', 'Special Vendors', 'Special vendors sell unique items not available elsewhere. Examples include the Argent Dawn vendors (for Stratholme), the Thorium Brotherhood vendors (for Blackrock Depths), or the Darkmoon Faire vendors. Some vendors require reputation or special currencies. Finding and accessing special vendors is part of efficient gearing strategies.', 'special vendors,argent dawn,thorium brotherhood,darkmoon faire,reputation,unique items,not available elsewhere,stratholme,blackrock depths,require reputation,special currencies,finding,accessing,efficient gearing,strategies', 'npcs,vendors,items,reputation');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_flight_masters', 'Flight Masters', 'Flight masters provide fast travel between locations via gryphons (Alliance) or wyverns (Horde). Learning flight paths is essential for efficient travel. Flight masters are located in major cities and towns. Some flight paths require reputation or quests to unlock. The flight network connects all major zones and makes exploration much easier.', 'flight masters,gryphons,wyverns,flight paths,travel,exploration,fast travel,alliance,horde,learning,essential,efficient travel,major cities,towns,require reputation,quests to unlock,flight network,connects all major zones,makes exploration easier', 'npcs,travel,flight,exploration');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_innkeepers', 'Innkeepers and Hearthstones', 'Innkeepers allow players to set their hearthstone location and provide rest benefits. Hearthstones provide instant travel back to the set location with a cooldown. Different innkeepers offer different rest rates. Some inns have special features like mailboxes or vendors. Managing hearthstone location is important for efficient gameplay.', 'innkeepers,hearthstones,rest,travel,cooldown,mailbox', 'npcs,travel,rest,hearthstone');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_banker', 'Bankers and Guild Banks', 'Bankers provide access to personal bank storage. Guild banks provide shared storage for guild members. Bankers are located in major cities. Guild banks have tabs and permissions that can be managed by officers. Using banks effectively is essential for managing large amounts of items and materials.', 'bankers,guild banks,storage,tabs,permissions,inventory,personal bank storage,shared storage,guild members,major cities,managed by officers,using banks effectively,managing large amounts,items,materials', 'npcs,storage,guild,inventory');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_auctioneers', 'Auctioneers', 'Auctioneers manage the auction house where players can buy and sell items. They are located in major cities. Auctioneers handle posting auctions, bidding, and collecting winnings. Understanding how to use the auction house effectively is crucial for the in-game economy. Different cities have different auction houses with varying activity levels.', 'auctioneers,auction house,buy,sell,bid,economy,manage,players can buy and sell,located in major cities,posting auctions,bidding,collecting winnings,understanding,use effectively,crucial,in game economy,different cities,varying activity levels', 'npcs,economy,trading,auction');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_stable_masters', 'Stable Masters', 'Stable masters allow players to store mounts and pets when not in use. Players can have multiple mounts and switch between them. Stables are located near major cities. Some stables offer special services or have unique mounts available. Managing mounts through stables helps keep inventory space free for other items.', 'stable_masters,mounts,pets,storage,inventory,management', 'npcs,mounts,pets,storage');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_lore_figures', 'Important Lore Figures', 'Many NPCs are important figures in Warcraft lore. Examples include Medivh (the Last Guardian), Illidan Stormrage, or Sylvanas Windrunner. These characters have rich backstories and often provide quests or dialogue that advances the game''s narrative. Learning about lore figures enhances the gaming experience and understanding of the world.', 'lore figures,medivh,illidan,sylvanas,backstories,narrative,important figures,warcraft lore,last guardian,illidan stormrage,sylvanas windrunner,rich backstories,provide quests,dialogue,advances the game,learning about,enhances gaming experience,understanding of the world', 'npcs,lore,story,characters');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_faction_leaders', 'Faction Leaders', 'Faction leaders guide their organizations and provide quests and reputation. Examples include Cairne Bloodhoof (Thunder Bluff), Tyrande Whisperwind (Darnassus), or Varian Wrynn (Stormwind). Faction leaders often have complex storylines and political motivations. Interacting with faction leaders helps players understand the geopolitical landscape of Azeroth.', 'faction leaders,cairne bloodhoof,tyrande whisperwind,varian wrynn,politics,guide their organizations,provide quests,reputation,thunder bluff,darnassus,stormwind,complex storylines,political motivations,interacting with,helps players understand,geopolitical landscape,azeroth', 'npcs,factions,leaders,politics');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_merchants', 'Specialized Merchants', 'Specialized merchants sell specific types of goods. Weapon merchants, armorers, reagent vendors, poison vendors. Some merchants are only available in certain locations or require special access. Finding the right merchants is important for gearing up and obtaining necessary supplies. Different merchants offer different quality and selection of goods.', 'specialized merchants,weapons,armor,reagents,poisons,supplies,sell specific types,weapon merchants,armorers,reagent vendors,poison vendors,certain locations,require special access,finding the right,important for gearing up,obtaining necessary,different quality,selection of goods', 'npcs,merchants,goods,supplies');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_guards', 'City Guards and Sentries', 'Guards protect cities and provide security. They attack hostile players and creatures. Guards have different levels and abilities based on the city. Some guards provide directions or information. Guards help maintain order in cities and make them safe for players. Different races have different guard appearances and behaviors.', 'city guards,sentries,security,protection,directions,order,protect cities,attack hostile players,creatures,different levels,abilities,based on the city,provide directions,information,maintain order,safe for players,different races,guard appearances,behaviors', 'npcs,guards,security,cities');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('npc_transport', 'Transportation NPCs', 'Various NPCs provide transportation services. Boat captains, zeppelin masters, portal trainers. Examples include the zeppelin between Orgrimmar and Undercity, or the boat from Booty Bay to Ratchet. Transportation NPCs make long-distance travel faster and more convenient. Some transportation requires tickets or has schedules.', 'transportation,boat captains,zeppelin masters,portals,tickets,schedules,provide transportation services,portal trainers,examples include,zeppelins,orgrimmar,undercity,boat,booty bay,ratchet,long distance travel,faster,more convenient,requires tickets,has schedules', 'npcs,transport,travel,convenience');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_alchemy', 'Alchemy Profession', 'Alchemy is a primary profession in World of Warcraft that allows players to create potions, elixirs, flasks, and transmutation recipes. Key skills include creating healing potions, mana potions, combat elixirs, and guardian elixirs. Master Alchemists can create powerful flasks that provide major stat bonuses. Alchemy requires herbs gathered by Herbalism and is essential for raiding and PvP.', 'alchemy,potions,elixirs,flasks,herbs,transmutation,mana,healing', 'profession,crafting,consumables,raiding,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_blacksmithing', 'Blacksmithing Profession', 'Blacksmithing is a primary profession focused on creating weapons, armor, and tools from metal ores. Blacksmiths can craft swords, axes, maces, plate armor, shields, and various tools. Specializations include Armorsmithing and Weaponsmithing. High-level blacksmiths create epic weapons and armor sets essential for end-game content.', 'blacksmithing,weapons,armor,plate,tools,metal,ore,warrior,paladin', 'profession,crafting,weapons,armor,raiding,warrior,paladin');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_enchanting', 'Enchanting Profession', 'Enchanting allows players to disenchant magical items to extract dusts, essences, and shards, then use these materials to create enchantments for weapons and armor. Popular enchants include spell power, attack power, critical strike, and stamina bonuses. Enchanting provides essential item enhancements for all classes and is highly profitable on the auction house.', 'enchanting,disenchant,dust,essences,shards,enchants,spell power', 'profession,crafting,enhancements,auction house,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_engineering', 'Engineering Profession', 'Engineering is a versatile profession that creates guns, explosives, mechanical devices, and various gadgets. Engineers can build scopes for ranged weapons, explosives for mining, repair bots, and flying machines. Specializations include Goblin and Gnomish engineering, each offering unique recipes. Engineering provides unique items not available through other professions.', 'engineering,guns,explosives,gadgets,scopes,repair bots,devices', 'profession,crafting,devices,specialized,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_herbalism', 'Herbalism Profession', 'Herbalism is a gathering profession that allows players to collect herbs from the world for use in Alchemy and Inscription. Common herbs include Peacebloom, Silverleaf, Briarthorn, and more rare ones like Felweed and Netherbloom. Herbalists can find herb nodes while traveling and track them on the minimap. It''s often paired with Alchemy for self-sufficiency.', 'herbalism,herbs,gathering,peacebloom,silverleaf,briarthorn,alchemy,inscription', 'profession,gathering,materials,alchemy,inscription');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_inscription', 'Inscription Profession', 'Inscription creates scrolls, glyphs, vellums, and off-hand books using pigments made from herbs. Inscribers can create glyphs that modify spell effects, research tomes for faster leveling, and Darkmoon cards for unique effects. It''s a scribe profession that provides essential spell modifications and cosmetic items.', 'inscription,glyphs,scrolls,pigments,research,darkmoon cards,spells', 'profession,crafting,spell mods,cosmetic,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_jewelcrafting', 'Jewelcrafting Profession', 'Jewelcrafting creates rings, necklaces, gems, and figurines using gems and metals. Jewelcrafters can cut gems to add socket bonuses, create epic jewelry with powerful stats, and craft trinkets. Specializations include gem cutting and metalworking. It''s highly valuable for creating high-end gear and auction house profits.', 'jewelcrafting,gems,rings,necklaces,sockets,jewelry,trinkets', 'profession,crafting,jewelry,sockets,valuable,all classes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_leatherworking', 'Leatherworking Profession', 'Leatherworking creates leather and mail armor, bags, and other leather goods using leather from skinning. Leatherworkers can craft armor sets, specialty bags, and drums. Specializations include Dragonscale, Elemental, and Tribal leatherworking, each with unique recipes. Essential for leather-wearing classes and provides good armor options.', 'leatherworking,leather,armor,bags,drums,mail,druid,rogue,hunter', 'profession,crafting,armor,bags,leather classes,druid,rogue,hunter');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_mining', 'Mining Profession', 'Mining is a gathering profession that collects ores and stones from mineral nodes for use in Blacksmithing, Engineering, and Jewelcrafting. Miners can find copper, tin, iron, gold, and rare ores like adamantite and fel iron. Mining provides essential materials for crafting professions and can be combined with Engineering for explosives to find more nodes.', 'mining,ores,stones,copper,iron,gold,adamantite,blacksmithing,engineering,jewelcrafting', 'profession,gathering,materials,crafting,blacksmithing,engineering,jewelcrafting');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_skinning', 'Skinning Profession', 'Skinning allows players to skin dead animal and humanoid corpses for leather and hides used in Leatherworking. Skinners can gather light leather, medium leather, heavy leather, and rare hides. It''s often paired with Leatherworking for self-sufficiency and provides materials for armor crafting. Skinning is essential for leather-based professions.', 'skinning,leather,hides,corpses,light leather,medium leather,leatherworking', 'profession,gathering,materials,leatherworking');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_tailoring', 'Tailoring Profession', 'Tailoring creates cloth armor, bags, shirts, and other cloth goods using cloth from tailors or drops. Tailors can craft robes, cloaks, bags, and specialty items. Specializations include Mooncloth, Shadoweave, and Spellfire tailoring, each with unique recipes. Essential for cloth-wearing classes like mages, priests, and warlocks.', 'tailoring,cloth,armor,bags,robes,cloaks,mage,priest,warlock', 'profession,crafting,armor,bags,cloth classes,mage,priest,warlock');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_cooking', 'Cooking Profession', 'Cooking is a secondary profession that lets players prepare food that provides buffs and stat bonuses. Recipes range from basic breads and stews to powerful feasts that grant raid-wide bonuses. Cooking often uses ingredients gathered from fish and drops and is valuable for raiding and leveling. Some expansions add unique cooking buffs and world event recipes.', 'cooking,food,recipes,feasts,buffs,stat bonuses,ingredients,consumables', 'profession,secondary,consumables,buffs,raiding');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_fishing', 'Fishing Profession', 'Fishing is a secondary gathering profession that lets players catch fish and other items from water sources. Fish are used as ingredients for Cooking and some crafting recipes. Fishing can also yield rare items, reagents, and collectibles. Specialized lures, poles, and fishing skills improve catch rates and access to rare catches.', 'fishing,fish,gathering,poles,lures,catches,ingredients,cooking', 'profession,secondary,gathering,materials,consumables');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('profession_first_aid', 'First Aid Profession', 'First Aid is a secondary profession every character can learn, used to craft bandages for out-of-combat healing (and, at lower ranks, limited use in combat, subject to a shared cooldown between bandages). The current top-rank bandage, Dense Frostweave Bandage, needs 450 skill and Frostweave Cloth from Northrend cloth drops. It is especially valuable for classes without a reliable self-heal, and doesn''t require reagents beyond the bandage itself.', 'first aid,bandages,healing,consumables,out of combat,survival', 'profession,secondary,consumables,healing,solo');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('mage_professions_guide', 'Best Professions for Mages', 'For mages, the best professions are typically Tailoring (for cloth armor and bags), Enchanting (for spell power enchants and disenchanting), and Alchemy (for mana potions and flasks). Tailoring allows mages to create their own gear and is essential for cloth wearers. Enchanting provides valuable spell power enchants for weapons and armor. Alchemy creates mana regeneration items crucial for spellcasters.', 'mage,professions,profession,tailoring,enchanting,alchemy,cloth,spell power,mana', 'profession,mage,cloth classes,spellcaster');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('warrior_professions_guide', 'Best Professions for Warriors', 'For warriors, the best professions are Blacksmithing (for plate armor and weapons), Mining (for ore materials), and Engineering (for utility items and repairs). Blacksmithing allows warriors to create their own plate armor and weapons. Mining provides the essential ores needed for blacksmithing. Engineering offers repair bots and other useful combat utilities.', 'warrior,professions,profession,blacksmithing,mining,engineering,plate,armor,weapons', 'profession,warrior,plate classes,melee');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('paladin_professions_guide', 'Best Professions for Paladins', 'For paladins, the best professions are Blacksmithing (for plate armor), Mining (for materials), Enchanting (for holy and spell power enchants), and Jewelcrafting (for jewelry and trinkets). Blacksmithing enables paladins to create their own plate armor. Enchanting provides essential spell power and holy enchants. Jewelcrafting offers valuable jewelry with healing and spell power stats.', 'paladin,professions,profession,blacksmithing,mining,enchanting,jewelcrafting,plate,holy,healing', 'profession,paladin,plate classes,healer,tank');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('hunter_professions_guide', 'Best Professions for Hunters', 'For hunters, the best professions are Leatherworking (for leather armor), Skinning (for leather materials), Engineering (for guns, scopes, and ammo), and Mining (for engineering materials). Leatherworking allows hunters to create their own leather armor. Engineering provides guns, scopes for better ranged damage, and repair bots. Skinning pairs perfectly with leatherworking for self-sufficiency.', 'hunter,professions,profession,leatherworking,skinning,engineering,guns,scopes,ammo,ranged', 'profession,hunter,leather classes,ranged');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('rogue_professions_guide', 'Best Professions for Rogues', 'For rogues, the best professions are Leatherworking (for leather armor), Skinning (for materials), Engineering (for utility gadgets and lockpicking), and Enchanting (for agility and critical strike enchants). Leatherworking enables rogues to create their own leather armor. Engineering provides useful gadgets and potentially lockpicking tools. Enchanting offers agility and critical strike enhancements crucial for rogue damage.', 'rogue,professions,profession,leatherworking,skinning,engineering,enchanting,agility,critical strike,stealth', 'profession,rogue,leather classes,melee,stealth');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('priest_professions_guide', 'Best Professions for Priests', 'For priests, the best professions are Tailoring (for cloth armor), Enchanting (for spell power and intellect enchants), Alchemy (for mana potions), and Inscription (for healing and spell modification glyphs). Tailoring allows priests to create their own cloth armor. Enchanting provides spell power enchants essential for healing and damage. Inscription offers glyphs that modify priest spells and abilities.', 'priest,professions,profession,tailoring,enchanting,alchemy,inscription,healing,cloth,spell power', 'profession,priest,cloth classes,healer,caster');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('shaman_professions_guide', 'Best Professions for Shamans', 'For shamans, the best professions are Leatherworking (for leather/mail armor), Skinning (for materials), Mining (for blacksmithing/engineering materials), and Enchanting (for spell power enchants). Leatherworking enables shamans to create their own leather or mail armor. Mining provides materials for crafting professions. Enchanting offers spell power enchants crucial for shaman elemental and healing spells.', 'shaman,professions,profession,leatherworking,skinning,mining,enchanting,elemental,healing,enhancement', 'profession,shaman,leather classes,healer,caster,melee');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('warlock_professions_guide', 'Best Professions for Warlocks', 'For warlocks, the best professions are Tailoring (for cloth armor), Enchanting (for spell power enchants), Alchemy (for mana and health potions), and Jewelcrafting (for soul stones and trinkets). Tailoring allows warlocks to create their own cloth armor. Enchanting provides spell power enchants for damage spells. Alchemy creates essential mana and health potions for warlock sustainability.', 'warlock,professions,profession,tailoring,enchanting,alchemy,jewelcrafting,cloth,spell power,demonology', 'profession,warlock,cloth classes,caster');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('druid_professions_guide', 'Best Professions for Druids', 'For druids, the best professions are Leatherworking (for leather armor), Skinning (for materials), Herbalism (for alchemy materials), and Alchemy (for consumables and potions). Leatherworking enables druids to create their own leather armor. Skinning pairs with leatherworking for self-sufficiency. Alchemy provides potions useful for druid healing and mana regeneration in various forms.', 'druid,professions,profession,leatherworking,skinning,herbalism,alchemy,healing,restoration,balance', 'profession,druid,leather classes,healer,caster,melee');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_battlegrounds', 'Battlegrounds', 'Battlegrounds are instanced PvP areas where teams compete for objectives. Warsong Gulch (capture the flag), Arathi Basin (resource control), Alterac Valley (massive battle with multiple objectives). Players earn honor points for victories and can purchase PvP gear. Battlegrounds require teamwork and strategy. Winning battlegrounds provides marks of honor used for epic gear.', 'battlegrounds,warsong gulch,arathi basin,alterac valley,honor,marks,instanced pvp areas,teams compete,objectives,capture the flag,resource control,massive battle,multiple objectives,earn honor points,victories,purchase pvp gear,require teamwork,strategy,winning,marks of honor,epic gear', 'pvp,battlegrounds,teamwork,honor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_arenas', 'Arena Combat', 'Arena combat pits small teams (2v2, 3v3, 5v5) against each other in fast-paced matches. Players earn arena points for victories, which are used to purchase rated gear. Arena requires high skill and coordination. Top arena players compete in tournaments and earn titles. Arena gear is among the best available for PvP.', 'arena,2v2,3v3,5v5,arena points,rated gear,tournaments,arena combat,small teams,fast paced matches,earn arena points,victories,purchase,requires high skill,coordination,top arena players,compete in,earn titles,among the best,available for pvp', 'pvp,arena,skill,competition');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_world_pvp', 'World PvP', 'World PvP occurs in the open world where players can attack each other. Popular spots include Tarren Mill vs Southshore in the Hillsbrad Foothills and the Gurubashi Arena in Stranglethorn Vale, plus Wintergrasp, Northrend''s dedicated open-world PvP zone where up to 40 players a side besiege a fortress with siege vehicles on a recurring timer. World PvP requires awareness and can be very rewarding. World PvP creates memorable moments and rivalries.', 'world pvp,tarren mill,gurubashi,awareness,rivalries,open world,players can attack,popular spots,southshore,wintergrasp,gurubashi arena,requires awareness,very rewarding,special rules,objectives,creates memorable moments', 'pvp,world,open_world,rivalries');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_ranks', 'PvP Ranks and Titles', 'The old Vanilla system of 14 numbered PvP ranks was replaced when the honor system was overhauled in the Burning Crusade: honor points are now spent directly on gear instead of being ground through ranks. The prestigious ''Grand Marshal'' (Alliance) and ''High Warlord'' (Horde) titles still exist, but are now awarded to the single highest-rated arena player of each class and faction at the end of a PvP season, alongside seasonal Gladiator titles for the top-rated teams. Titles are prestigious and show PvP dedication.', 'pvp ranks,titles,grand marshal,high warlord,gladiator,prestige,pvp season,top rated,alliance,horde,prestigious,show pvp dedication', 'pvp,ranks,titles,prestige');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_gear_progression', 'PvP Gear Progression', 'PvP gear is obtained through honor and arena points. Low-level PvP gear from battleground marks, higher level gear from honor purchases, top-tier gear from arena points. PvP sets provide resilience and PvP power. Players can mix PvP and PvE gear for hybrid builds. Good PvP gear is essential for competitive play.', 'pvp gear,honor,arena points,resilience,hybrid builds,competitive,obtained through,low level pvp gear,battleground marks,higher level gear,honor purchases,top tier gear,pvp sets,provide resilience,pvp power,mix pvp and pve,good pvp gear,essential for,competitive play', 'pvp,gear,progression,equipment');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_faction_conflicts', 'Faction Conflicts', 'Major faction conflicts drive PvP activity. The longstanding Alliance vs Horde war, the battle for Azeroth, conflicts with the Scourge or Burning Legion. These conflicts provide context for PvP battles and create stakes. Understanding faction lore enhances PvP experiences. Major conflicts often have world events and special PvP content.', 'faction conflicts,alliance,horde,scourge,burning legion,lore,major faction conflicts,drive pvp activity,longstanding war,battle for azeroth,conflicts with,provide context,pvp battles,create stakes,understanding faction lore,enhances pvp experiences,world events,special pvp content', 'pvp,factions,conflicts,lore');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_strategies', 'PvP Strategies and Tactics', 'Successful PvP requires different strategies than PvE. Focus on crowd control, burst damage, and survivability. Know class matchups and counters. Use terrain and positioning. Coordinate with team members. PvP often involves trading cooldowns and managing resources. Adapting to different situations is key to victory.', 'pvp strategies,crowd control,burst damage,matchups,coordination,cooldowns,successful pvp,different strategies,pve,focus on,survivability,know class,counters,use terrain,positioning,coordinate with team,trading cooldowns,managing resources,adapting to,different situations,key to victory', 'pvp,strategies,tactics,skill');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_honor_system', 'Honor System', 'The honor system rewards PvP participation. Honor points are earned from killing enemy players and winning objectives. Honor decays weekly and resets seasonally. Honor is used to purchase PvP gear and weapons. The honor grind requires consistent PvP activity. Honor rankings show the top PvP players each season.', 'honor system,honor points,decay,rankings,seasonal,grind,rewards pvp participation,earned from,killing enemy players,winning objectives,decays weekly,resets seasonally,used to purchase,pvp gear,weapons,honor grind,requires consistent,pvp activity,honor rankings,show the top,pvp players,each season', 'pvp,honor,system,rewards');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_ganking', 'Ganking and Ambush Tactics', 'Ganking involves high-level players attacking lower-level players. This controversial tactic is common in world PvP. Players use stealth, speed, and surprise to ambush enemies. Ganking can be frustrating but is part of the PvP experience. Some areas are notorious for ganking. Players learn to be aware and prepared.', 'ganking,ambush,stealth,surprise,controversial,awareness', 'pvp,tactics,ganking,controversy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_objectives', 'Battleground Objectives', 'Each battleground has specific objectives to complete. Warsong Gulch: capture enemy flag and return to base. Arathi Basin: control resource nodes. Alterac Valley: destroy enemy towers and generals. Eye of the Storm: control the central flag. Understanding objectives is crucial for victory. Teams coordinate to achieve goals efficiently.', 'battleground objectives,capture flag,resource nodes,towers,coordination,each battleground,specific objectives,warsong gulch,capture enemy flag,return to base,arathi basin,control resource nodes,alterac valley,destroy enemy towers,generals,eye of the storm,control the central flag,understanding objectives,crucial for victory,teams coordinate,achieve goals,efficiently', 'pvp,objectives,battlegrounds,strategy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_team_composition', 'Team Composition', 'Good team composition is essential for PvP success. Balance healers, tanks, and damage dealers. Include crowd control and utility classes. Different compositions work for different battlegrounds. Arena teams are built around synergies and counters. Understanding class roles helps build better teams. Communication about composition improves performance.', 'team composition,healers,tanks,damage,crowd control,synergies,good team composition,essential for,pvp success,balance healers,damage dealers,include crowd control,utility classes,different compositions,work for,different battlegrounds,arena teams,built around,counters,understanding class roles,helps build,better teams,communication about,improves performance', 'pvp,teams,composition,strategy');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_gear_specialization', 'PvP vs PvE Gear', 'PvP gear focuses on resilience and PvP power, while PvE gear focuses on raw damage/healing. Players choose based on playstyle. Hybrid gear mixes both. PvP gear often has unique appearances. Some players prefer pure PvP or PvE progression. Gear choice affects performance in different content types.', 'pvp gear,pve gear,resilience,hybrid,playstyle,performance,focuses on,pvp power,raw damage,healing,players choose,based on playstyle,hybrid gear,mixes both,unique appearances,prefer pure,pvp or pve,progression,gear choice,affects performance,different content types', 'pvp,gear,specialization,choice');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_psychology', 'PvP Psychology and Mindset', 'PvP requires mental toughness and adaptability. Dealing with losses, managing tilt, staying focused. Understanding opponent psychology. Using mind games and deception. PvP is as much mental as physical. Developing the right mindset leads to better performance. Learning from defeats is crucial for improvement.', 'pvp psychology,mindset,tilt,adaptability,mind games,improvement,requires mental toughness,dealing with losses,managing tilt,staying focused,understanding opponent,psychology,using mind games,deception,as much mental,physical,developing the right,leads to better,performance,learning from defeats,crucial for', 'pvp,psychology,mindset,mental');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_community', 'PvP Community and Culture', 'PvP has a strong community with rivalries, friendships, and traditions. Top players become celebrities. PvP guilds focus on competition. Community events and tournaments. Toxic behavior exists but good sportsmanship is valued. PvP community creates lasting bonds and memorable experiences. Being part of PvP community enhances enjoyment.', 'pvp_community,rivalries,tournaments,sportsmanship,bonds,culture', 'pvp,community,culture,social');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('pvp_rewards', 'PvP Rewards and Incentives', 'PvP offers various rewards beyond gear. Titles, mounts, achievements, special tabards. Seasonal rewards for top performers. Unique PvP items and cosmetics. Rewards motivate participation and competition. Some rewards are very rare and prestigious. PvP rewards system encourages continued engagement and improvement.', 'pvp rewards,titles,mounts,achievements,seasonal,prestigious,offers various rewards,beyond gear,special tabards,seasonal rewards,top performers,unique pvp items,cosmetics,rewards motivate,participation,competition,very rare,pvp rewards system,encourages continued,engagement,improvement', 'pvp,rewards,incentives,motivation');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_class_stories', 'Class-Specific Storylines', 'Each class has unique quests that tell their story. Paladins have the Silver Hand storyline, warlocks have demonic pacts, hunters have beast mastery. Class quests provide unique items and abilities. They often involve important lore figures. Completing class quests enhances understanding of class identity and provides powerful rewards.', 'class stories,paladin,warlock,hunter,silver hand,lore,identity,each class,unique quests,tell their story,silver hand storyline,demonic pacts,beast mastery,provide unique items,abilities,important lore figures,completing class quests,enhances understanding,powerful rewards', 'quests,story,class,lore');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_zone_storylines', 'Zone Story Arcs', 'Each zone has a main storyline that guides players through the area. Examples include the Defias Brotherhood in Westfall, the Scourge invasion in the Plaguelands, or the silithid threat in Silithus. Zone stories connect to larger world events. Following zone storylines provides better loot and understanding of the world.', 'zone storylines,defias brotherhood,scourge,silithid,world events,loot,each zone,main storyline,guides players,through the area,westfall,scourge invasion,plaguelands,silithid threat,silithus,connect to larger,following zone storylines,provides better loot,understanding of the world', 'quests,story,zones,progression');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_reputation_grinds', 'Reputation Quest Hubs', 'Many factions have extensive quest lines for reputation. The Cenarion Circle in Silithus, the Argent Dawn in the Plaguelands, the Thorium Brotherhood in Searing Gorge. Reputation quests often involve grinding specific activities. High reputation unlocks better rewards and access to exclusive content.', 'reputation quests,cenarion circle,argent dawn,thorium brotherhood,grinding,many factions,extensive quest lines,silithus,plaguelands,searing gorge,involve grinding,specific activities,high reputation,unlocks better rewards,access to,exclusive content', 'quests,reputation,grinding,rewards');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_dungeon_quests', 'Dungeon and Raid Quests', 'Many dungeons and raids have associated quests. Blackrock Depths has the Dark Iron dwarves storyline, Stratholme has the Scourge invasion quests. Dungeon quests often provide attunement or access to harder content. They explain the dungeon''s lore and provide additional rewards beyond boss loot.', 'dungeon quests,blackrock depths,stratholme,attunement,lore,rewards,many dungeons,raids,associated quests,dark iron dwarves,storyline,scourge invasion quests,provide attunement,access to harder content,explain the dungeon,additional rewards,beyond boss loot', 'quests,dungeons,raids,lore');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_world_events', 'World Event Quests', 'Major world events have extensive quest lines. The Ahn''Qiraj War Effort required collecting resources across Azeroth. The Scourge Invasion had defense quests in major cities. World event quests involve massive coordination and provide unique rewards. They create memorable experiences for the entire playerbase.', 'world event quests,ahnqiraj,scourge invasion,coordination,memorable,major world events,extensive quest lines,ahn qiraj war effort,required collecting,resources across azeroth,defense quests,major cities,involve massive coordination,provide unique rewards,create memorable experiences,entire playerbase', 'quests,events,world,coordination');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_epic_questlines', 'Epic Quest Chains', 'Some quests form long, involved storylines. The Warlock artifact quests, the Paladin epic mounts, the Hunter epic bow quests. Epic quests often span multiple zones and require significant time investment. They provide the most powerful and unique rewards in the game.', 'epic questlines,warlock artifacts,paladin mounts,hunter bow,investment,some quests,form long,involved storylines,warlock artifact quests,paladin epic mounts,hunter epic bow quests,span multiple zones,require significant,time investment,provide the most,powerful,unique rewards,in the game', 'quests,epic,storylines,rewards');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_profession_quests', 'Profession Quest Lines', 'Professions have quests that advance their story. Blacksmithing has the Dark Iron quests, alchemy has the Elixir of Vigor, fishing has the Nat Pagle quests. Profession quests provide recipes, tools, and understanding of the profession''s lore. They often require gathering rare materials or completing difficult tasks.', 'profession quests,blacksmithing,alchemy,fishing,recipes,tools,professions have quests,advance their story,dark iron quests,elixir of vigor,nat pagle quests,provide recipes,understanding of,profession lore,require gathering,rare materials,completing difficult tasks', 'quests,professions,lore,recipes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_faction_conflicts', 'Faction Conflict Quests', 'Quests that involve Alliance vs Horde conflicts. The battle for Ashenvale, the wars in the Plaguelands, the Stromgarde conflicts. These quests provide context for world PvP and create stakes for faction loyalty. They often involve attacking enemy cities or defending territory.', 'faction_conflicts,alliance,horde,ashenvale,plaguelands,stromgarde', 'quests,factions,conflicts,pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_lore_quests', 'Lore-Revealing Quests', 'Quests that reveal important Warcraft lore. The story of Medivh and the Dark Portal, the fall of Quel''Thalas, the corruption of the orcs. These quests often involve reading books, speaking to NPCs, or exploring ancient ruins. They enhance understanding of the game''s rich history and mythology.', 'lore_quests,medivh,dark_portal,quelthalas,orcs,history', 'quests,lore,story,history');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_escort_quests', 'Escort and Protection Quests', 'Quests where players must escort NPCs to destinations while protecting them from enemies. Examples include escorting the druid to Moonglade or protecting the caravan in Thousand Needles. Escort quests can be challenging due to mob aggro and pathing issues. They often provide good rewards for successful completion.', 'escort quests,protection,druid,caravan,challenging,rewards,players must escort,npcs to destinations,protecting them,from enemies,escorting the druid,moonglade,protecting the caravan,thousand needles,due to mob aggro,pathing issues,provide good rewards,successful completion', 'quests,escort,protection,challenging');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_collection_quests', 'Collection and Gathering Quests', 'Quests that require collecting specific items. Gathering rare herbs, killing specific mobs for drops, finding hidden objects. Examples include the collection quests in Un''Goro Crater or the breadcrumb quests in zones. These quests teach exploration and efficient farming techniques.', 'collection quests,gathering,herbs,drops,exploration,farming,require collecting,specific items,gathering rare herbs,killing specific mobs,finding hidden objects,un goro crater,breadcrumb quests,zones,teach exploration,efficient farming,techniques', 'quests,collection,gathering,exploration');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_timed_quests', 'Timed and Race Quests', 'Quests with time limits or racing elements. Racing against other players, completing objectives before time runs out. Examples include the race to the finish in certain zones or timed defense quests. These quests require speed and efficiency. They often provide bonus rewards for fast completion.', 'timed quests,racing,speed,efficiency,bonus rewards,defense,time limits,racing elements,racing against other players,completing objectives,before time runs out,race to the finish,certain zones,timed defense quests,require speed,provide bonus rewards,fast completion', 'quests,timed,racing,speed');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_group_quests', 'Group and Raid Quests', 'Quests designed for groups or raids. The Molten Core attunement quests, the Ahn''Qiraj opening quests. These quests require coordination and often involve difficult combat. They provide access to endgame content and powerful rewards. Group quests teach teamwork and strategy.', 'group quests,raid quests,molten core,ahnqiraj,coordination,teamwork,designed for groups,raids,molten core attunement,ahn qiraj opening,require coordination,difficult combat,provide access,endgame content,powerful rewards,teach teamwork,strategy', 'quests,group,raid,coordination');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_repeatable_quests', 'Repeatable and Daily Quests', 'Quests that can be completed multiple times. Daily quests for reputation, repeatable quests for gold or items. Examples include the Cenarion Circle dailies or the fishing daily quests. Repeatable quests provide ongoing activities and rewards. They help with gearing and reputation grinding.', 'repeatable quests,daily quests,cenarion circle,fishing,ongoing,grinding,completed multiple times,daily quests for reputation,repeatable quests for gold,items,cenarion circle dailies,fishing daily quests,provide ongoing activities,rewards,help with gearing,reputation grinding', 'quests,repeatable,daily,grinding');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('quest_hidden_quests', 'Hidden and Secret Quests', 'Quests not obviously marked on the map. Hidden quests require exploration, talking to specific NPCs, or discovering secret areas. Examples include the quest for the Green Hills of Stranglethorn pages or the hidden quests in Blackrock Mountain. Finding hidden quests provides satisfaction and unique rewards.', 'hidden quests,secret quests,exploration,green hills,blackrock mountain,satisfaction,not obviously marked,on the map,require exploration,talking to specific npcs,discovering secret areas,quest for the,green hills of stranglethorn,pages,hidden quests in,finding hidden quests,provides satisfaction,unique rewards', 'quests,hidden,secret,exploration');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_hallows_end', 'Hallow''s End', 'Hallow''s End runs each year from October 18 to October 31, decorating capital cities with pumpkins and letting players trick-or-treat at candy buckets in every inn for random treats, including a small chance at the flying Magic Broom mount. Its centerpiece is a fight against the Headless Horseman, summoned in Scarlet Monastery''s graveyard; since patch 3.3.3 he can be queued for directly through the Dungeon Finder instead of forming a group by hand. Players can also throw Weighted Jack-o''-Lanterns and pick up a costume wand that turns them into a ghost, ninja, or wickerman for the duration of the holiday.', 'hallow''s end,headless horseman,magic broom,trick or treat,candy bucket,scarlet monastery', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_winter_veil', 'Feast of Winter Veil', 'The Feast of Winter Veil is WoW''s Christmas-themed holiday, running from December 15 through January 2. Players collect a daily gift from under the tree beside Greatfather Winter in Ironforge or Orgrimmar, buy toys and treats from the traveling Smokywood Pastures vendor, and can start snowball fights or use a Handful of Snowflakes to turn friends into reindeer. There is no dedicated Winter Veil mount, but achievements like Merrymaker (completing every holiday task) award a title, and the classic ''Metzen the Reindeer'' summon is a well-known joke item tied to the season.', 'feast of winter veil,winter veil,greatfather winter,smokywood pastures,reindeer,snowball', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_brewfest', 'Brewfest', 'Brewfest runs from September 20 to October 4 at fairgrounds outside Ironforge and Orgrimmar, where players ram-race, sample brews from the Brewfest quartermaster for tokens, and fight the drunken boss Coren Direbrew inside Blackrock Depths (also queueable through the Dungeon Finder). Defeating Direbrew drops a loot bag with a chance at the Great Brewfest Kodo or the Swift Brewfest Ram mount, making his fight the event''s main draw for collectors. The Brewfest Trade Chief reputation, raised through daily quests, unlocks additional holiday-only gear and trinkets.', 'brewfest,coren direbrew,brewfest kodo,brewfest ram,ram racing,blackrock depths', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_midsummer_fire_festival', 'Midsummer Fire Festival', 'The Midsummer Fire Festival burns from June 21 to July 4 around bonfires placed in most major cities and zones. Players tend their own faction''s flame, try to douse the rival faction''s fire and relight their own from it, and dance around the Ribbon Pole for a festive buff; visiting every bonfire and completing the fire-themed dailies works toward the Fire Festival meta-achievement and title. Rewards are mostly cosmetic -- torch-tossing toys and a Brazier of Dancing Flames trinket -- with no dedicated mount tied to the holiday.', 'midsummer fire festival,bonfire,ribbon pole,torch,brazier of dancing flames', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_lunar_festival', 'Lunar Festival', 'Lunar Festival runs from February 1 to February 14 and centers on visiting Elders scattered across nearly every zone on both continents, each granting the Elders'' Blessing buff and a bit of Lunar Festival lore. Players also toss coins into the fountain at Moonglade for a random small reward, and can take on Omen, a spectral fire elemental that spawns as a group-killable target in Moonglade for the duration of the event. Collecting blessings from enough Elders unlocks the elder title and a fireworks-launching trinket.', 'lunar festival,elders,elders'' blessing,moonglade,omen,coin toss', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_love_is_in_the_air', 'Love is in the Air', 'Love is in the Air runs from February 10 to February 23; Wrath of the Lich King''s patch 3.0.8 expanded it from a minor vanilla holiday into a full event centered on a farcical boss fight against Apothecary Hummel and his gang of thugs in each capital city. Defeating Hummel drops a loot bag with a small chance at the Big Love Rocket, one of the game''s most sought-after rare mounts. Players also collect Lovely Charms from monsters everywhere to trade for perfume, cologne, and the companion pet Peddlefeet, and can propose to friends with a Silver Bell or invite them to disco-dance atop a caged Love Fool.', 'love is in the air,apothecary hummel,big love rocket,lovely charms,peddlefeet', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_childrens_week', 'Children''s Week', 'Children''s Week runs from April 30 to May 6. Players adopt a war orphan from the Orphan Matron in their faction''s capital and escort it on a tour of iconic locations, including a Northrend leg added for Wrath of the Lich King that has players take their orphan through Icecrown or Borean Tundra. It is also when the School of Hard Knocks achievement is available, which specifically requires knocking Northrend school children into the water with snowballs -- a joke only possible once Wrath''s zones exist. Completing the full questline awards a faction-specific orphan companion pet.', 'children''s week,orphan,orphan matron,school of hard knocks,companion pet', 'event,holiday,seasonal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('event_pilgrims_bounty', 'Pilgrim''s Bounty', 'Pilgrim''s Bounty is WoW''s Thanksgiving-themed holiday, added with Wrath of the Lich King and running from November 21 to November 27 at a feast table set up outside every major city. Players cook and serve dishes like Cranberry Chutney, Pumpkin Pie, and Slow-Roasted Turkey to seated guests of both factions for reputation and Pilgrim''s Bounty Buckets, and can earn the Pilgrim''s Paunch food-coma buff for overeating. The Turkinator achievement, earned by killing wild turkeys that spawn worldwide during the event, rounds out the holiday''s meta-achievement.', 'pilgrim''s bounty,turkinator,pilgrim''s paunch,cranberry chutney,thanksgiving', 'event,holiday,seasonal,wotlk');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_elwynn_forest', 'Elwynn Forest', 'Elwynn Forest is the starting zone for Human players in Stormwind. This peaceful forested area contains Northshire Abbey where new players learn basic skills. Key locations include Goldshire (the main town), Northshire Valley, and the forests around Stormwind. Common mobs include wolves, bears, kobolds, and bandits. Players can find quests from guards, farmers, and townsfolk. This zone teaches basic combat, gathering professions, and introduces players to World of Warcraft gameplay.', 'elwynn,forest,human,starting,zone,goldshire,northshire,stormwind,peaceful forested area,northshire abbey,new players,learn basic skills,key locations,main town,northshire valley,forests around,common mobs,wolves,bears,kobolds,bandits,find quests,guards,farmers,townsfolk,teaches basic combat,gathering professions,introduces players,world of warcraft,gameplay', 'zone,starting_area,human,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_durotar', 'Durotar', 'Durotar is the starting zone for Orc and Troll players in Orgrimmar. This harsh desert and canyon region contains the Valley of Trials where new players learn basic skills. Key locations include Orgrimmar (the main city), Razor Hill, and the Echo Isles. Common enemies include boars, scorpids, quilboars, and centaurs. Players receive quests from various NPCs and learn about Horde culture and combat. This zone introduces players to shamanistic elements and Horde traditions.', 'durotar,orc,troll,starting,zone,orgrimmar,razor hill,valley of trials,harsh desert,canyon region,new players,learn basic skills,key locations,main city,echo isles,common enemies,boars,scorpids,quilboars,centaurs,receive quests,various npcs,learn about,horde culture,combat,introduces players,shamanistic elements,horde traditions', 'zone,starting_area,horde,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_teldrassil', 'Teldrassil', 'Teldrassil is the starting zone for Night Elf players in Darnassus. This massive tree contains Shadowglen where new players begin their journey. Key areas include Darnassus (the capital city), Dolanaar, and the forests of Teldrassil. Players learn druidic magic and nature-based combat. Common creatures include spiders, owls, and corrupted furbolgs. This zone emphasizes nature magic, stealth, and Night Elf culture.', 'teldrassil,night,elf,starting,zone,darnassus,dolanaar,shadowglen', 'zone,starting_area,alliance,night_elf,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_mulgore', 'Mulgore', 'Mulgore is the starting zone for Tauren players in Thunder Bluff. This vast plains region contains Bloodhoof Village where new players learn basic skills. Key locations include Thunder Bluff (the main city), Red Cloud Mesa, and the plains of Mulgore. Players learn about shamanism, hunting, and Tauren spirituality. Common enemies include wolves, cougars, and hostile centaurs. This zone teaches players about the elements and Tauren culture.', 'mulgore,tauren,starting,zone,thunder bluff,bloodhoof,plains,vast plains region,bloodhoof village,new players,learn basic skills,key locations,main city,red cloud mesa,plains of mulgore,learn about,shamanism,hunting,tauren spirituality,common enemies,wolves,cougars,hostile centaurs,teaches players,about the elements,tauren culture', 'zone,starting_area,horde,tauren,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_dun_morogh', 'Dun Morogh', 'Dun Morogh is the starting zone for Dwarf and Gnome players in Ironforge. This mountainous region contains Anvilmar where new players begin. Key locations include Ironforge (the main city), Kharanos, and the Coldridge Valley. Players learn engineering, mining, and blacksmithing. Common enemies include troggs, wolves, and dark iron dwarves. This zone emphasizes technology, crafting, and dwarven culture.', 'dun morogh,dwarf,gnome,starting,zone,ironforge,kharanos,coldridge,mountainous region,anvilmar,new players,begin,key locations,main city,coldridge valley,learn engineering,mining,blacksmithing,common enemies,troggs,wolves,dark iron dwarves,emphasizes technology,crafting,dwarven culture', 'zone,starting_area,alliance,dwarf,gnome,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_tirisfal_glades', 'Tirisfal Glades', 'Tirisfal Glades is the starting zone for Undead players in the Undercity. This haunted region contains Deathknell where new players rise as Forsaken. Key locations include the Undercity, Brill, and the forests of Tirisfal. Players learn about the Scourge, undeath, and Forsaken society. Common enemies include zombies, ghouls, and Scarlet Crusade members. This zone introduces players to the Forsaken struggle and undead themes.', 'tirisfal,glades,undead,forsaken,starting,zone,undercity,deathknell', 'zone,starting_area,horde,undead,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_azuremyst_isle', 'Azuremyst Isle', 'Azuremyst Isle is the starting zone for Draenei players in the Exodar. This crashed spaceship island contains the Crash Site where new players begin. Key locations include the Exodar (the capital city), Azure Watch, and the forests of Azuremyst. Players learn about the Light, technology, and Draenei culture. Common enemies include nagas, owlbears, and corrupted wildlife. This zone introduces players to the Draenei exodus and their technological heritage.', 'azuremyst,isle,draenei,starting,zone,exodar,crash site,azure watch,crashed spaceship island,new players,begin,key locations,capital city,forests of azuremyst,learn about,the light,technology,draenei culture,common enemies,nagas,owlbears,corrupted wildlife,introduces players,draenei exodus,technological heritage', 'zone,starting_area,alliance,draenei,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_eversong_woods', 'Eversong Woods', 'Eversong Woods is the starting zone for Blood Elf players in Silvermoon City. This magical forest contains Sunstrider Isle where new players learn basic skills. Key locations include Silvermoon City, Falconwing Square, and the forests of Eversong. Players learn about arcane magic, addiction to magic, and Blood Elf society. Common enemies include wraiths, mana creatures, and hostile wildlife. This zone introduces players to Blood Elf culture and the magic addiction struggle.', 'eversong,woods,blood,elf,starting,zone,silvermoon,sunstrider,magical forest,sunstrider isle,new players,learn basic skills,key locations,silvermoon city,falconwing square,forests of eversong,learn about,arcane magic,addiction to magic,blood elf society,common enemies,wraiths,mana creatures,hostile wildlife,introduces players,blood elf culture,magic addiction,struggle', 'zone,starting_area,horde,blood_elf,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_borean_tundra', 'Borean Tundra', 'Borean Tundra is a level 68-72 zone in Northrend, the icy northern continent. This frozen wasteland contains major cities like Valiance Keep (Alliance) and Warsong Hold (Horde). Key areas include the Riplash Ruins, the Geyser Fields, and the coastline. Players can find quests involving the Scourge, nerubians, and the blue dragonflight. This zone features diverse environments from icy plains to geothermal areas and introduces players to Northrend''s harsh climate.', 'borean,tundra,northrend,level 68,valiance keep,warsong hold,riplash,icy northern continent,frozen wasteland,major cities,alliance,horde,key areas,riplash ruins,geyser fields,coastline,find quests,involving the scourge,nerubians,blue dragonflight,features diverse environments,icy plains,geothermal areas,introduces players,northrend harsh climate', 'zone,northrend,leveling,wrath,contested');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_howling_fjord', 'Howling Fjord', 'Howling Fjord is a level 68-72 zone in Northrend featuring dramatic fjords and viking-inspired settlements. Alliance players start at Valgarde while Horde players start at Camp Winterhoof. Key areas include Utgarde Keep, the Dragonflayer area, and the coastal regions. Players encounter vrykul, wolves, and various wildlife. This zone contains both questing areas and instances, making it a hub for Northrend adventurers.', 'howling,fjord,northrend,level 68,valgarde,camp winterhoof,utgarde,dramatic fjords,viking inspired settlements,alliance players,start at,horde players,key areas,utgarde keep,dragonflayer area,coastal regions,encounter vrykul,wolves,various wildlife,contains both,questing areas,instances,making it a hub,northrend adventurers', 'zone,northrend,leveling,wrath,contested');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_westfall', 'Westfall', 'Westfall is a level 10 to 20 Alliance zone of failing farmland west of Elwynn Forest. The Defias Brotherhood and their harvest golems have overrun the farms, and the People''s Militia works out of Sentinel Hill. It holds the entrance to the Deadmines and the long-running Defias questline, and Alliance players usually quest here right after Elwynn.', 'westfall,sentinel hill,defias brotherhood,harvest golem,peoples militia,deadmines entrance,moonbrook,farmland', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_loch_modan', 'Loch Modan', 'Loch Modan is a level 10 to 20 dwarven zone east of Dun Morogh, built around a great lake and the Stonewrought Dam. Thelsamar is the quest hub. Troggs, kobolds, and the Dark Iron dwarves press in from the hills, and the Explorers'' League digs at the Farstrider Lodge and Ironband''s excavation site.', 'loch modan,thelsamar,stonewrought dam,the loch,ironbands excavation,farstrider lodge,troggs,dark iron dwarves', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_silverpine_forest', 'Silverpine Forest', 'Silverpine Forest is a level 10 to 20 Horde zone south of Tirisfal Glades, dark and worgen-haunted. The Sepulcher is the Forsaken quest hub, and Shadowfang Keep sits at its southern edge above Pyrewood Village. Dalaran''s old magical dome once stood here, and the Dalaran mages still hold ruins in the east.', 'silverpine forest,silverpine,the sepulcher,shadowfang keep entrance,pyrewood village,worgen,ambermill,forsaken zone', 'zone,horde,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_ghostlands', 'Ghostlands', 'Ghostlands is a level 10 to 20 blood elf zone south of Eversong Woods, scarred by the Scourge''s march on Quel''Thalas. Tranquillien is the quest hub, and the Dead Scar cuts through the middle of the zone. It leads on to Zul''Aman and connects Silvermoon''s territory to the rest of the Eastern Kingdoms.', 'ghostlands,tranquillien,dead scar,quelthalas,zulaman entrance,blood elf leveling,scourge', 'zone,horde,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_redridge_mountains', 'Redridge Mountains', 'Redridge Mountains is a level 15 to 25 Alliance zone east of Elwynn Forest, centered on Lakeshire and its broken bridge. Blackrock orcs push down from Render''s Camp in the north and gnolls hold the southern hills. It borders Duskwood to the south and the Burning Steppes far to the north.', 'redridge mountains,redridge,lakeshire,blackrock orcs,renders camp,lake everstill,stonewatch,gnolls', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_duskwood', 'Duskwood', 'Duskwood is a level 18 to 30 zone of permanent night south of Elwynn Forest, with Darkshire as its quest hub. Worgen, undead, and spiders roam the roads, and the Night Watch patrols nervously. It holds the Stalvan Mistmantle and Mor''Ladim questlines, Raven Hill Cemetery, and the entrance to Deadwind Pass in the east.', 'duskwood,darkshire,night watch,raven hill,raven hill cemetery,morladim,stalvan mistmantle,worgen,twilight grove', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_hillsbrad_foothills', 'Hillsbrad Foothills', 'Hillsbrad Foothills is a level 20 to 30 contested zone below Alterac, famous for open world PvP between Tarren Mill and Southshore. The Forsaken hold Tarren Hill in the north and the Alliance hold Southshore on the coast. Durnholde Keep and the Syndicate occupy the eastern hills.', 'hillsbrad foothills,hillsbrad,tarren mill,southshore,durnholde keep,the syndicate,world pvp,azurelode mine', 'zone,contested,eastern_kingdoms,leveling,pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_wetlands', 'Wetlands', 'Wetlands is a level 20 to 30 Alliance-leaning zone of marsh and rain north of Dun Morogh, with Menethil Harbor as its port and quest hub. Raptors, murlocs, and crocolisks make the roads dangerous for the level range. Boats from Menethil run to Theramore in Kalimdor and to Howling Fjord in Northrend.', 'wetlands,menethil harbor,raptors,murlocs,crocolisk,dun modr,grim batol,boat to theramore', 'zone,alliance,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_arathi_highlands', 'Arathi Highlands', 'Arathi Highlands is a level 30 to 40 contested zone of open grassland, with Refuge Pointe for the Alliance and Hammerfall for the Horde. Stromgarde Keep lies ruined in the southwest, contested by the Syndicate and Boulderfist ogres. The Arathi Basin battleground takes its name and setting from this zone.', 'arathi highlands,arathi,refuge pointe,hammerfall,stromgarde keep,boulderfist ogres,the syndicate,arathi basin', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_alterac_mountains', 'Alterac Mountains', 'Alterac Mountains is a level 30 to 40 contested snow zone between Hillsbrad and the Hinterlands. The ruins of Alterac city are held by the Syndicate, and yetis and ogres fill the valleys. It is thinly quested compared to its neighbours, and its main draw is the entrance to Alterac Valley in the north.', 'alterac mountains,alterac,ruins of alterac,the syndicate,yeti,ogres,alterac valley entrance,dalaran crater', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_stranglethorn_vale', 'Stranglethorn Vale', 'Stranglethorn Vale is a level 30 to 45 contested jungle at the south end of the Eastern Kingdoms, notorious for world PvP along its single road. Booty Bay in the far south is a neutral goblin port with an auction house. Grom''gol Base Camp serves the Horde, Rebel Camp the Alliance, and Zul''Gurub sits in the eastern jungle.', 'stranglethorn vale,stranglethorn,booty bay,gromgol base camp,rebel camp,nesingwary,zulgurub entrance,jungle,world pvp,bloodsail buccaneers', 'zone,contested,eastern_kingdoms,leveling,pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_badlands', 'Badlands', 'Badlands is a level 35 to 45 contested canyon zone south of Loch Modan, all red rock and dust. Kargath serves the Horde and the Dwarven District of Thelsamar supplies the Alliance side from the north. Its main feature is the entrance to Uldaman, and black dragonkin and Dark Iron dwarves contest the excavation sites.', 'badlands,kargath,uldaman entrance,angor fortress,black dragonkin,dark iron,canyon,lethlor ravine', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_swamp_of_sorrows', 'Swamp of Sorrows', 'Swamp of Sorrows is a level 35 to 45 contested marsh east of Duskwood, sunk in permanent fog and rain. Stonard is the Horde outpost, and the Alliance has no real foothold. The Sunken Temple lies beneath the Temple of Atal''Hakkar in the north of the zone, and the Dark Portal sits just east in the Blasted Lands.', 'swamp of sorrows,stonard,sunken temple,temple of atalhakkar,misty valley,pool of tears,marsh,dragonkin', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_hinterlands', 'The Hinterlands', 'The Hinterlands is a level 40 to 50 contested forest north of the Plaguelands, home to the Wildhammer dwarves at Aerie Peak and the Revantusk trolls on the eastern coast. Vilebranch and Witherbark forest trolls hold most of the zone. Aerie Peak is also the entrance to Seradane and a common Alliance flight point.', 'the hinterlands,hinterlands,aerie peak,wildhammer dwarves,revantusk village,vilebranch trolls,witherbark,forest trolls,jintha alor', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_searing_gorge', 'Searing Gorge', 'Searing Gorge is a level 43 to 50 contested zone of ash and open flame between the Badlands and the Burning Steppes. The Thorium Brotherhood works out of Thorium Point, and the Dark Iron dwarves hold the Slag Pit and Blackrock. It is the surface approach to Blackrock Depths and a prime mining zone for thorium.', 'searing gorge,thorium point,thorium brotherhood,dark iron dwarves,the slag pit,blackrock depths approach,thorium mining,cauldrons', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_blasted_lands', 'Blasted Lands', 'Blasted Lands is a level 45 to 55 contested wasteland at the southern tip of the Eastern Kingdoms, and it holds the Dark Portal to Outland. Nethergarde Keep serves the Alliance and Dreadmaul Hold the Horde. Players crossing to Outland at level 58 pass through here, so the zone stays busy well past its own level range.', 'blasted lands,dark portal,nethergarde keep,dreadmaul hold,outland entrance,portal to outland,rise of the defiler,felhounds', 'zone,contested,eastern_kingdoms,leveling,outland_gateway');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_burning_steppes', 'Burning Steppes', 'Burning Steppes is a level 50 to 58 contested zone of lava and black rock, north of Redridge and below Blackrock Mountain. Morgan''s Vigil holds the Alliance camp and Flame Crest the Horde. The zone is the front door to Blackrock Spire and Molten Core, and Dark Iron dwarves and black dragonkin patrol the roads.', 'burning steppes,morgans vigil,flame crest,blackrock mountain,blackrock spire entrance,molten core entrance,black dragonkin,dark iron', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_western_plaguelands', 'Western Plaguelands', 'Western Plaguelands is a level 51 to 58 contested zone of Scourge-blighted farmland, with Chillwind Camp for the Alliance and the Bulwark on the Horde approach. Andorhal lies ruined at its center and Hearthglen in the north is held by the Scarlet Crusade. Scholomance sits on Caer Darrow in the southeast.', 'western plaguelands,chillwind camp,andorhal,hearthglen,caer darrow,scholomance entrance,scarlet crusade,the bulwark,scourge', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_eastern_plaguelands', 'Eastern Plaguelands', 'Eastern Plaguelands is a level 53 to 60 contested zone and the darkest ground in the Eastern Kingdoms, with the Argent Dawn holding Light''s Hope Chapel against the Scourge. Stratholme lies in the northwest behind its gates, and Naxxramas floated above the zone before it moved to Northrend. The plaguewood and Blackwood are thick with undead.', 'eastern plaguelands,lights hope chapel,argent dawn,stratholme entrance,plaguewood,tyrs hand,scourge,corins crossing', 'zone,contested,eastern_kingdoms,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_deadwind_pass', 'Deadwind Pass', 'Deadwind Pass is a level 55 to 60 contested corridor between Duskwood and the Swamp of Sorrows, and it has almost no quests of its own. Its reason to exist is Karazhan, Medivh''s tower, which looms over the southern end of the pass and is the entry raid of the Burning Crusade.', 'deadwind pass,karazhan,medivh,medivhs tower,deadwind,ogres,no quests', 'zone,contested,eastern_kingdoms');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_isle_of_queldanas', 'Isle of Quel''Danas', 'Isle of Quel''Danas is a level 70 daily quest island north of Quel''Thalas, added at the end of the Burning Crusade. Both factions share the Shattered Sun Offensive base there, and the zone unlocks progressively through server-wide phases. It holds Magisters'' Terrace and the Sunwell Plateau raid.', 'isle of queldanas,queldanas,shattered sun offensive,sunwell plateau,magisters terrace,daily quests,sunwell,level 70 dailies', 'zone,neutral,eastern_kingdoms,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_bloodmyst_isle', 'Bloodmyst Isle', 'Bloodmyst Isle is a level 10 to 20 draenei zone north of Azuremyst Isle, stained red by the crash of the Exodar. Blood Watch is the quest hub. It follows straight on from the draenei starting experience and ends around the level where players leave for Darkshore or Darnassus.', 'bloodmyst isle,bloodmyst,blood watch,draenei,exodar crash,vector coil,wrathscale naga', 'zone,alliance,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_darkshore', 'Darkshore', 'Darkshore is a level 10 to 20 night elf zone along the western coast of Kalimdor, below Teldrassil. Auberdine is the port and quest hub, with boats to Menethil Harbor, Rut''theran Village, and the Exodar. Ruins, murlocs, and the Twilight''s Hammer occupy the coast, and Blackfathom Deeps lies at the southern end.', 'darkshore,auberdine,night elf zone,blackfathom deeps entrance,twilights hammer,master craftsman,coast,boat', 'zone,alliance,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_the_barrens', 'The Barrens', 'The Barrens is the great level 10 to 25 Horde zone across central Kalimdor, split by the Gold Road and remembered for its chat channel. Crossroads is the main quest hub, with Camp Taurajo south and Ratchet on the eastern coast as a neutral goblin port. Wailing Caverns sits in the Wailing Caverns oasis in the north.', 'the barrens,barrens,crossroads,camp taurajo,ratchet,wailing caverns entrance,gold road,barrens chat,razorfen', 'zone,horde,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_stonetalon_mountains', 'Stonetalon Mountains', 'Stonetalon Mountains is a level 15 to 27 contested zone of pine ridges northwest of the Barrens. Sun Rock Retreat serves the Horde and Stonetalon Peak the Alliance. Venture Company goblins are logging the forest, which drives most of the zone''s quests, and the Charred Vale lies burnt in the south.', 'stonetalon mountains,stonetalon,sun rock retreat,stonetalon peak,venture company,charred vale,windshear crag,logging', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_ashenvale', 'Ashenvale', 'Ashenvale is a level 18 to 30 contested night elf forest north of the Barrens, heavily fought over by Warsong loggers and the Sentinels. Astranaar is the Alliance hub and Splintertree Post the Horde''s. Blackfathom Deeps lies on its western coast and the Warsong Lumber Camp drives the faction conflict here.', 'ashenvale,astranaar,splintertree post,warsong lumber camp,sentinels,silverwing,night elf forest,furbolg', 'zone,contested,kalimdor,leveling,pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_thousand_needles', 'Thousand Needles', 'Thousand Needles is a level 25 to 35 contested zone of towering mesas and dry canyons south of the Barrens. Freewind Post sits atop a mesa as the Horde hub. The Shimmering Flats in the southeast host the goblin racetrack, and centaur and Grimtotem tauren hold the canyon floor.', 'thousand needles,freewind post,shimmering flats,mirage raceway,goblin racetrack,centaur,grimtotem,mesas,razorfen downs', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_desolace', 'Desolace', 'Desolace is a level 30 to 40 contested wasteland on Kalimdor''s western coast, grey and thinly populated. Nijel''s Point serves the Alliance and Shadowprey Village the Horde. Centaur clans war across the middle of the zone and Maraudon''s entrance lies in the Valley of Spears in the south.', 'desolace,nijels point,shadowprey village,maraudon entrance,valley of spears,centaur clans,kodo graveyard,wasteland', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_dustwallow_marsh', 'Dustwallow Marsh', 'Dustwallow Marsh is a level 35 to 45 contested swamp on Kalimdor''s eastern coast, holding the Alliance city of Theramore Isle under Jaina Proudmoore and the Horde camp at Brackenwall Village. Onyxia''s Lair sits in the wyrmbog to the south, and Mudsprocket in the southwest was added as a later goblin hub.', 'dustwallow marsh,theramore isle,theramore,jaina proudmoore,brackenwall village,onyxias lair entrance,the wyrmbog,mudsprocket,swamp', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_feralas', 'Feralas', 'Feralas is a level 40 to 50 contested jungle in southwestern Kalimdor, thick with yeti, ogres, and gorillas. Feathermoon Stronghold serves the Alliance from an island in the west and Camp Mojache the Horde. Dire Maul lies in the ruins of Eldre''Thalas at the center of the zone.', 'feralas,feathermoon stronghold,camp mojache,dire maul entrance,eldrethalas,yeti,gordunni ogres,high wilderness', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_tanaris', 'Tanaris', 'Tanaris is a level 40 to 50 contested desert in southern Kalimdor, with the neutral goblin port of Gadgetzan as its hub and an auction house. The Caverns of Time open in the Tanaris cliffs, and Zul''Farrak lies in the northwest. Silithid, pirates at Lost Rigger Cove, and basilisks fill the sands.', 'tanaris,gadgetzan,caverns of time,zulfarrak entrance,lost rigger cove,steamwheedle port,desert,silithid,noggenfogger', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_azshara', 'Azshara', 'Azshara is a level 45 to 55 contested zone in northeastern Kalimdor, overgrown and lightly quested before Cataclysm reworked it. Valormok is the Horde camp and Talrendis Point the Alliance''s. Naga hold the ruins along the coast and the Timbermaw and blue dragonflight both have interests in the north.', 'azshara,valormok,talrendis point,naga,ruins of eldarath,bay of storms,blue dragonflight,legash encampment', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_felwood', 'Felwood', 'Felwood is a level 48 to 55 contested zone north of Ashenvale, corrupted by demonic taint into sickly green forest. Emerald Sanctuary and Whisperwind Grove hold the Cenarion Circle''s efforts to cleanse it. Timbermaw Hold in the north is a neutral furbolg faction worth grinding for the shortcut it opens to Winterspring and Moonglade.', 'felwood,emerald sanctuary,whisperwind grove,timbermaw hold,cenarion circle,corrupted furbolg,demonic taint,irontree woods', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_ungoro_crater', 'Un''Goro Crater', 'Un''Goro Crater is a level 48 to 55 contested prehistoric basin south of Silithus, full of devilsaurs, raptors, and elementals. Marshal''s Refuge in the middle is the neutral hub, and the crater is one of the best places in the old world for herbs, ore, and power crystals. A devilsaur will kill an unprepared player of its level range.', 'ungoro crater,ungoro,marshals refuge,devilsaur,dinosaurs,power crystals,fire plume ridge,golakka hot springs,raptors', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_silithus', 'Silithus', 'Silithus is a level 55 to 60 contested desert in southwestern Kalimdor, crawling with silithid and the Twilight''s Hammer cult. Cenarion Hold is the quest hub and the Cenarion Circle reputation grind runs from there. The gates of Ahn''Qiraj stand at the zone''s southern edge, opening onto the two Ahn''Qiraj raids.', 'silithus,cenarion hold,silithid,twilights hammer,ahnqiraj gates,scarab lord,cenarion circle,bug hives', 'zone,contested,kalimdor,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_winterspring', 'Winterspring', 'Winterspring is a level 55 to 60 contested snow zone in northeastern Kalimdor, with the neutral goblin town of Everlook as its hub. Frostsabers, yeti, and chimaera roam the drifts. It holds the Frostsaber mount grind for night elves and heavy thorium and arcane crystal mining in the Mazthoril caves.', 'winterspring,everlook,frostsaber,yeti,chimaera,mazthoril,starfall village,snow,arcane crystal', 'zone,contested,kalimdor,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_moonglade', 'Moonglade', 'Moonglade is a small neutral sanctuary valley in northern Kalimdor, sacred to druids and reachable by the Teleport: Moonglade spell any druid learns at level 14. Nighthaven is its only settlement, home to the Cenarion Circle and Remulos. It has no hostile mobs and no level range: druids come here for class quests and everyone else for the Lunar Festival.', 'moonglade,nighthaven,druid sanctuary,teleport moonglade,cenarion circle,keeper remulos,lunar festival,no mobs,timbermaw tunnel', 'zone,neutral,kalimdor,sanctuary,druid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_hellfire_peninsula', 'Hellfire Peninsula', 'Hellfire Peninsula is the level 58 to 63 entry zone of Outland, the red broken land on the far side of the Dark Portal. Honor Hold serves the Alliance and Thrallmar the Horde. Hellfire Citadel sits at the center with Ramparts, Blood Furnace, Shattered Halls, and Magtheridon''s Lair, and the zone has a heavy world PvP presence around its towers.', 'hellfire peninsula,hellfire,honor hold,thrallmar,dark portal,hellfire citadel,ramparts,blood furnace,magtheridon,outland entry', 'zone,contested,outland,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_zangarmarsh', 'Zangarmarsh', 'Zangarmarsh is a level 60 to 64 Outland zone of giant mushrooms and standing water, home to the Cenarion Expedition at Cenarion Refuge and the sporeggar mushroom folk. Telredor serves the Alliance and Zabra''jin the Horde. The Coilfang Reservoir instances, including Slave Pens, Underbog, Steamvault, and Serpentshrine Cavern, all open here.', 'zangarmarsh,cenarion expedition,sporeggar,telredor,zabrajin,coilfang reservoir,slave pens,underbog,steamvault,serpentshrine cavern,mushrooms', 'zone,contested,outland,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_terokkar_forest', 'Terokkar Forest', 'Terokkar Forest is a level 62 to 65 Outland zone of tall bone-white trees, and it surrounds Shattrath City. Allerian Stronghold serves the Alliance and Stonebreaker Hold the Horde. Auchindoun sits in the Bone Wastes at its center with four wings, and the Skettis arakkoa hold the southeast.', 'terokkar forest,terokkar,shattrath,allerian stronghold,stonebreaker hold,auchindoun,bone wastes,skettis,arakkoa,lower city', 'zone,contested,outland,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_nagrand', 'Nagrand', 'Nagrand is a level 64 to 67 Outland zone of green plains and floating islands, widely considered the best-looking zone of the Burning Crusade. Telaar serves the Alliance and Garadar the Horde, and the Mag''har orcs quest chain runs from Garadar. Halaa in the center is a world PvP objective, and the Ring of Blood is a well-known group quest gauntlet.', 'nagrand,telaar,garadar,maghar orcs,halaa,ring of blood,floating islands,throne of the elements,world pvp', 'zone,contested,outland,leveling,pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_blades_edge_mountains', 'Blade''s Edge Mountains', 'Blade''s Edge Mountains is a level 65 to 68 Outland zone of jagged spires, ogre holds, and dragon bones driven into the rock. Sylvanaar serves the Alliance and Thunderlord Stronghold the Horde. Gruul''s Lair opens in the northwest and the Ogri''la plateau in the east unlocks daily quests at level 70.', 'blades edge mountains,blades edge,sylvanaar,thunderlord stronghold,gruuls lair,ogrila,bladespire,dragon bones,skyguard', 'zone,contested,outland,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_netherstorm', 'Netherstorm', 'Netherstorm is a level 67 to 70 Outland zone of shattered floating landmass and arcane storms in the northeast. Area 52 is the neutral goblin hub, and the Consortium and Kirin Tor both operate here. Tempest Keep, with the Arcatraz, Botanica, Mechanar, and Eye, sits at the zone''s western edge as Kael''thas Sunstrider''s stronghold.', 'netherstorm,area 52,tempest keep,arcatraz,botanica,mechanar,the eye,kaelthas sunstrider,manaforge,consortium', 'zone,contested,outland,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_shadowmoon_valley', 'Shadowmoon Valley', 'Shadowmoon Valley is a level 67 to 70 Outland zone of black rock and lava in the southeast, and the last leveling zone of the Burning Crusade. Wildhammer Stronghold serves the Alliance and Shadowmoon Village the Horde. The Black Temple, Illidan Stormrage''s fortress, dominates the middle of the zone, and the Netherwing ledge offers drake mount dailies at level 70.', 'shadowmoon valley,black temple,illidan stormrage,wildhammer stronghold,shadowmoon village,netherwing ledge,netherwing drake,altar of sha,coilskar', 'zone,contested,outland,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_dragonblight', 'Dragonblight', 'Dragonblight is a level 71 to 74 Northrend zone at the center of the continent, where dragons come to die. Wintergarde Keep serves the Alliance and Agmar''s Hammer the Horde, with the neutral Wyrmrest Temple rising at the middle. Azjol-Nerub and the Old Kingdom open in the north, Naxxramas floats in the northeast, and the Wrathgate questline plays out here.', 'dragonblight,wyrmrest temple,wintergarde keep,agmars hammer,azjolnerub,old kingdom,naxxramas entrance,wrathgate,dragon graveyard', 'zone,contested,northrend,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_grizzly_hills', 'Grizzly Hills', 'Grizzly Hills is a level 73 to 75 Northrend zone of dense pine forest and logging camps, known for its music. Amberpine Lodge serves the Alliance and Conquest Hold the Horde. The Drakkari trolls, the Venture Company, and the worgen of Grizzlemaw drive most of the questing, and Drak''Tharon Keep sits on the border with Zul''Drak.', 'grizzly hills,amberpine lodge,conquest hold,grizzlemaw,draktharon keep,venture company,furbolg,worgen,pine forest', 'zone,contested,northrend,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_zuldrak', 'Zul''Drak', 'Zul''Drak is a level 74 to 76 Northrend zone, the ice troll homeland, where the Drakkari are killing their own gods for power. The Argent Crusade holds Light''s Breach and the Ebon Blade operates at Ebon Watch. Gundrak sits at the northern end of the zone, and the Amphitheater of Anguish runs a well-known gauntlet of group quests.', 'zuldrak,drakkari,ice trolls,gundrak,lights breach,ebon watch,amphitheater of anguish,troll gods,argent crusade', 'zone,contested,northrend,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_sholazar_basin', 'Sholazar Basin', 'Sholazar Basin is a level 76 to 78 Northrend zone, a tropical valley sealed inside the ice and untouched by the Lich King. Nesingwary''s camp runs the hunting quests, and the Oracles and the Frenzyheart Tribe are opposed reputations: siding with one locks out the other, and each offers its own dailies and pets.', 'sholazar basin,sholazar,the oracles,frenzyheart tribe,nesingwary,river mouth,tropical,titan,mysterious egg', 'zone,neutral,northrend,leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_storm_peaks', 'The Storm Peaks', 'The Storm Peaks is a level 76 to 80 Northrend zone of high mountains and titan architecture in the north, home to the Sons of Hodir. K3 is the goblin hub and Dun Niffelem the Sons of Hodir''s. The Sons of Hodir reputation is the only source of shoulder enchants in Wrath, and Ulduar opens from the western side of the zone.', 'the storm peaks,storm peaks,sons of hodir,dun niffelem,k3,ulduar entrance,titan,brunnhildar,shoulder enchants,hyldnir', 'zone,contested,northrend,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_icecrown', 'Icecrown', 'Icecrown is the level 77 to 80 Northrend zone below the Lich King''s fortress, and the last leveling zone of Wrath. The Argent Crusade, the Knights of the Ebon Blade, and the Alliance and Horde all hold camps here. The Argent Tournament grounds run mounted daily quests, and Icecrown Citadel with the Trial of the Crusader sits at the zone''s heart.', 'icecrown,icecrown citadel,lich king,argent tournament,knights of the ebon blade,argent crusade,trial of the crusader,shadow vault,saronite', 'zone,contested,northrend,leveling,endgame');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_crystalsong_forest', 'Crystalsong Forest', 'Crystalsong Forest is a level 77 to 80 Northrend zone of crystalline trees at the center of the continent, directly beneath the floating city of Dalaran. It has very few quests of its own and exists mostly as the approach to Dalaran and a passage between Dragonblight, Zul''Drak, and the Storm Peaks.', 'crystalsong forest,crystalsong,dalaran below,crystalline trees,windrunners overlook,sunreavers command,few quests,transit zone', 'zone,contested,northrend');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`) VALUES ('zone_wintergrasp', 'Wintergrasp', 'Wintergrasp is a level 77 to 80 Northrend zone that works as an open world PvP battleground rather than a leveling zone. Alliance and Horde fight over the Wintergrasp Fortress on a timer using siege vehicles and destructible walls. Holding the fortress grants the winning faction access to the Vault of Archavon raid and a damage buff, and losing it locks that out until the next battle.', 'wintergrasp,world pvp,siege vehicles,wintergrasp fortress,vault of archavon,tenacity,battle timer,destructible walls,pvp zone', 'zone,contested,northrend,pvp,endgame');
